import js from '@eslint/js';
import globals from 'globals';
import next from 'eslint-config-next';
import tailwindcssPlugin from 'eslint-plugin-tailwindcss';

// `next lint` was removed in Next.js 16 — ESLint runs directly via
// `npm run lint` (eslint .). The eslint-config-next flat preset covers
// js/jsx/ts/tsx (react, react-hooks, import, jsx-a11y, @next/next rules and
// the TypeScript parser); this file restores the project's extra rules.
export default [
  {
    // .eslintrc.cjs is the pre-flat-config RC file; ESLint v9 never reads it, so
    // it is excluded from linting instead of being treated as application source.
    ignores: ['dist', 'node_modules', '.next', '.eslintrc.cjs'],
  },
  ...next,
  {
    // eslint-config-next@16 bundles eslint-plugin-react-hooks v7, whose
    // "recommended" preset enables the compiler-oriented rules
    // (set-state-in-effect, purity, preserve-manual-memoization, refs, ...).
    // This project's contract is eslint-plugin-react-hooks v5 "recommended"
    // (rules-of-hooks + exhaustive-deps); the new rules flag the established
    // fetch-on-mount pattern across the legacy portals, and adopting the
    // compiler ruleset is a separate repository-wide migration.
    files: ['**/*.{js,jsx,mjs,cjs,ts,tsx,mts,cts}'],
    rules: {
      'react-hooks/static-components': 'off',
      'react-hooks/use-memo': 'off',
      'react-hooks/preserve-manual-memoization': 'off',
      'react-hooks/incompatible-library': 'off',
      'react-hooks/immutability': 'off',
      'react-hooks/globals': 'off',
      'react-hooks/refs': 'off',
      'react-hooks/set-state-in-effect': 'off',
      'react-hooks/error-boundaries': 'off',
      'react-hooks/purity': 'off',
      'react-hooks/set-state-in-render': 'off',
      'react-hooks/unsupported-syntax': 'off',
      'react-hooks/config': 'off',
      'react-hooks/gating': 'off',
    },
  },
  {
    files: ['**/*.{js,jsx,mjs,cjs}'],
    languageOptions: {
      ecmaVersion: 'latest',
      sourceType: 'module',
      globals: {
        ...globals.browser,
        ...globals.es2021,
      },
    },
    plugins: {
      tailwindcss: tailwindcssPlugin,
    },
    rules: {
      ...js.configs.recommended.rules,
      ...tailwindcssPlugin.configs.recommended.rules,
    },
  },
];

export default {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
};

import type { Metadata } from "next";
import "./globals.css";
import GlobalProviders from './GlobalProviders';

export const metadata: Metadata = {
  title: "VPD Technologies | Transforming Businesses Through Intelligent Digital Solutions",
  description: "VPD Technologies is a global engineering powerhouse driving digital transformation through AI, cloud, and secure-by-design enterprise software.",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en" className="scroll-smooth">
      <head>
        <link rel="preconnect" href="https://fonts.googleapis.com" />
        <link rel="preconnect" href="https://fonts.gstatic.com" crossOrigin="anonymous" />
        <link
          href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Inter:wght@400;500;600&family=Montserrat:wght@600;700&family=JetBrains+Mono:wght@400;500&display=swap"
          rel="stylesheet"
        />
        <link
          href="https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:wght,FILL@100..700,0..1&display=swap"
          rel="stylesheet"
        />
      </head>
      <body className="bg-surface dark:bg-dark-surface text-ink dark:text-dark-ink font-body antialiased overflow-x-hidden">
        <div id="root"><GlobalProviders>{children}</GlobalProviders></div>
      </body>
    </html>
  );
}

"use client";
import React, { createContext, useContext, useEffect, useState } from 'react';
import { User } from '../types/common.types';
import { authApi } from '../api/auth.api';

interface AuthContextType {
  user: User | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  login: (email: string, pass: string) => Promise<User>;
  logout: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(() => {
    try {
      const stored = localStorage.getItem('user');
      return stored ? JSON.parse(stored) : null;
    } catch {
      return null;
    }
  });
  const [isLoading, setIsLoading] = useState<boolean>(true);

  useEffect(() => {
    const checkSession = async () => {
      try {
        const res = await authApi.getMe();
        if (res.data?.user) {
          setUser(res.data.user);
          localStorage.setItem('user', JSON.stringify(res.data.user));
        }
      } catch (err: any) {
        // 401 = no valid session cookie; drop any stale cached user so protected
        // portals stay locked. Other errors (offline) keep the cached session.
        if (err?.status === 401) {
          setUser(null);
          localStorage.removeItem('user');
        }
      } finally {
        setIsLoading(false);
      }
    };
    checkSession();
  }, []);

  const login = async (email: string, pass: string): Promise<User> => {
    setIsLoading(true);
    try {
      const res = await authApi.login({ email, password: pass });
      const loggedUser = res.data.user;
      setUser(loggedUser);
      localStorage.setItem('user', JSON.stringify(loggedUser));
      return loggedUser;
    } finally {
      setIsLoading(false);
    }
  };

  const logout = async () => {
    try {
      await authApi.logout();
    } catch {
      // Ignore network errors on logout
    } finally {
      setUser(null);
      localStorage.removeItem('user');
      localStorage.removeItem('token');
      window.location.href = '/auth/login';
    }
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        isAuthenticated: !!user,
        isLoading,
        login,
        logout,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within an AuthProvider');
  return context;
};

export default AuthContext;

"use client";
import { useRouter, usePathname } from "next/navigation";
import React, { useState } from 'react';

import { useAuth } from '../../auth.context';
import { roleHome } from '../../role-route';

export const Login: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const { login } = useAuth();
  const navigate = useRouter();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !password) {
      setError('Please provide both your corporate email and password.');
      return;
    }
    setLoading(true);
    setError(null);
    try {
      const user = await login(email.trim(), password);
      navigate.push(roleHome(user.role));
    } catch (err: any) {
      setError(err.message || 'Invalid email or password. Please verify your credentials.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      style={{
        minHeight: '100vh',
        width: '100%',
        backgroundColor: '#0a0a0c',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: '24px 16px',
        boxSizing: 'border-box',
        position: 'relative',
        overflow: 'hidden',
        fontFamily: "'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      {/* Background radial accent glow */}
      <div
        style={{
          position: 'absolute',
          width: '450px',
          height: '450px',
          borderRadius: '50%',
          background: 'radial-gradient(circle, rgba(212,175,55,0.08) 0%, rgba(10,10,12,0) 70%)',
          pointerEvents: 'none',
          top: '50%',
          left: '50%',
          transform: 'translate(-50%, -50%)',
        }}
      />

      {/* Login Card */}
      <div
        style={{
          width: '100%',
          maxWidth: '420px',
          backgroundColor: '#121215',
          border: '1px solid #27272a',
          borderRadius: '16px',
          padding: '36px 32px',
          boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.85), 0 0 0 1px rgba(255, 255, 255, 0.03)',
          position: 'relative',
          zIndex: 10,
          boxSizing: 'border-box',
        }}
      >
        {/* Brand Logo & Title Header */}
        <div style={{ textAlign: 'center', marginBottom: '28px' }}>
          <div style={{ display: 'inline-flex', alignItems: 'center', justifyContent: 'center', marginBottom: '14px' }}>
            <img
              src="/logo.webp"
              alt="VPD Technologies"
              style={{
                height: '48px',
                width: 'auto',
                maxWidth: '180px',
                objectFit: 'contain',
                display: 'block',
              }}
            />
          </div>
          <h1
            style={{
              fontSize: '20px',
              fontWeight: '700',
              color: '#ffffff',
              margin: '0 0 6px 0',
              letterSpacing: '-0.02em',
            }}
          >
            Enterprise Access
          </h1>
          <p
            style={{
              fontSize: '13px',
              color: '#a1a1aa',
              margin: 0,
              lineHeight: '1.4',
            }}
          >
            Enter your corporate credentials to sign in
          </p>
        </div>

        {/* Error Notification */}
        {error && (
          <div
            style={{
              backgroundColor: 'rgba(239, 68, 68, 0.12)',
              border: '1px solid #ef4444',
              borderRadius: '10px',
              padding: '10px 14px',
              marginBottom: '20px',
              display: 'flex',
              alignItems: 'center',
              gap: '10px',
            }}
          >
            <span style={{ color: '#ef4444', fontWeight: 'bold', fontSize: '14px' }}>⚠</span>
            <p style={{ margin: 0, fontSize: '12px', color: '#fca5a5', lineHeight: '1.4' }}>{error}</p>
          </div>
        )}

        {/* Login Form */}
        <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '18px' }}>
          {/* Corporate Email Field */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
            <label
              htmlFor="email"
              style={{
                fontSize: '11px',
                fontWeight: '700',
                color: '#d4d4d8',
                letterSpacing: '0.06em',
                textTransform: 'uppercase',
              }}
            >
              Corporate Email
            </label>
            <input
              id="email"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="name@vpdtechnologies.com"
              required
              autoComplete="email"
              style={{
                width: '100%',
                padding: '11px 14px',
                backgroundColor: '#18181b',
                border: '1px solid #3f3f46',
                borderRadius: '10px',
                color: '#ffffff',
                fontSize: '14px',
                boxSizing: 'border-box',
                outline: 'none',
                transition: 'border-color 0.2s',
              }}
              onFocus={(e) => (e.target.style.borderColor = '#d4af37')}
              onBlur={(e) => (e.target.style.borderColor = '#3f3f46')}
            />
          </div>

          {/* Password Field */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
            <label
              htmlFor="password"
              style={{
                fontSize: '11px',
                fontWeight: '700',
                color: '#d4d4d8',
                letterSpacing: '0.06em',
                textTransform: 'uppercase',
              }}
            >
              Password
            </label>
            <div style={{ position: 'relative', width: '100%' }}>
              <input
                id="password"
                type={showPassword ? 'text' : 'password'}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="Enter password"
                required
                autoComplete="current-password"
                style={{
                  width: '100%',
                  padding: '11px 50px 11px 14px',
                  backgroundColor: '#18181b',
                  border: '1px solid #3f3f46',
                  borderRadius: '10px',
                  color: '#ffffff',
                  fontSize: '14px',
                  boxSizing: 'border-box',
                  outline: 'none',
                  transition: 'border-color 0.2s',
                }}
                onFocus={(e) => (e.target.style.borderColor = '#d4af37')}
                onBlur={(e) => (e.target.style.borderColor = '#3f3f46')}
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                aria-label={showPassword ? 'Hide password' : 'Show password'}
                style={{
                  position: 'absolute',
                  right: '10px',
                  top: '50%',
                  transform: 'translateY(-50%)',
                  background: 'transparent',
                  border: 'none',
                  color: showPassword ? '#dfc067' : '#a1a1aa',
                  padding: '6px',
                  borderRadius: '6px',
                  cursor: 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  transition: 'color 0.2s',
                }}
                onMouseEnter={(e) => ((e.currentTarget as HTMLElement).style.color = '#ffffff')}
                onMouseLeave={(e) => ((e.currentTarget as HTMLElement).style.color = showPassword ? '#dfc067' : '#a1a1aa')}
              >
                {showPassword ? (
                  // Eye slash icon (hide)
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24" />
                    <line x1="1" y1="1" x2="23" y2="23" />
                  </svg>
                ) : (
                  // Eye icon (show)
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" />
                    <circle cx="12" cy="12" r="3" />
                  </svg>
                )}
              </button>
            </div>
          </div>

          {/* Submit Sign In Button */}
          <button
            type="submit"
            disabled={loading}
            style={{
              width: '100%',
              marginTop: '6px',
              padding: '12px',
              backgroundColor: '#d4af37',
              color: '#09090b',
              fontWeight: '700',
              fontSize: '14px',
              borderRadius: '10px',
              border: 'none',
              cursor: loading ? 'not-allowed' : 'pointer',
              opacity: loading ? 0.7 : 1,
              transition: 'background-color 0.2s, transform 0.1s',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              gap: '8px',
              boxShadow: '0 4px 14px 0 rgba(212, 175, 55, 0.25)',
            }}
            onMouseEnter={(e) => {
              if (!loading) (e.target as HTMLElement).style.backgroundColor = '#dfc067';
            }}
            onMouseLeave={(e) => {
              if (!loading) (e.target as HTMLElement).style.backgroundColor = '#d4af37';
            }}
          >
            {loading ? 'Authenticating...' : 'Sign In'}
          </button>
        </form>
      </div>
    </div>
  );
};

export default Login;

"use client";
import Link from "next/link";
import { useRouter, usePathname } from "next/navigation";
import React, { useState } from 'react';
import { useAuth } from '../../context/AuthContext';

export interface PortalNavItem {
  path: string;
  label: string;
  icon?: React.ReactNode;
  badge?: React.ReactNode;
}

export interface PortalNavSection {
  title?: string;
  items: PortalNavItem[];
}

interface PortalLayoutProps {
  portalName: string;
  portalBadge?: string;
  navSections?: PortalNavSection[];
  children?: React.ReactNode;
}

export default function PortalLayout({
  portalName,
  portalBadge,
  navSections = [],
  children,
}: PortalLayoutProps) {
  const { user, logout } = useAuth();
  const navigate = useRouter();
  const pathname = usePathname();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  const handleLogout = async () => {
    try {
      await logout();
      navigate.push('/auth/login');
    } catch {
      navigate.push('/auth/login');
    }
  };

  return (
    <div className="min-h-screen bg-[#0a0a0a] text-zinc-100 flex flex-col md:flex-row antialiased">
      {/* Mobile Top Header */}
      <header className="md:hidden bg-[#121212] border-b border-[#2a2a2a] px-4 py-3 flex items-center justify-between sticky top-0 z-40">
        <div className="flex items-center gap-3">
          <img src="/logo.webp" alt="VPD Logo" className="h-7 w-auto object-contain" />
          <div className="flex flex-col">
            <span className="font-bold text-sm text-white tracking-tight leading-none">VPD Technologies</span>
            <span className="text-[10px] text-[#d4af37] font-medium leading-none mt-1">{portalName}</span>
          </div>
        </div>
        <button
          onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          className="p-2 rounded-lg bg-[#1a1a1a] text-zinc-300 hover:text-white"
        >
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d={mobileMenuOpen ? "M6 18L18 6M6 6l12 12" : "M4 6h16M4 12h16M4 18h16"} />
          </svg>
        </button>
      </header>

      {/* Sidebar Navigation */}
      <aside className={`
        fixed inset-y-0 left-0 z-50 w-64 bg-[#121212] border-r border-[#2a2a2a] flex flex-col justify-between transition-transform duration-200 ease-in-out
        md:translate-x-0 md:sticky md:top-0 md:h-screen md:w-64 md:shrink-0
        ${mobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        {/* Brand Header */}
        <div className="p-5 border-b border-[#2a2a2a]">
          <div className="flex items-center gap-3">
            <img src="/logo.webp" alt="VPD Logo" className="h-8 w-auto object-contain" />
            <div className="flex flex-col">
              <span className="font-bold text-sm text-white tracking-wider">VPD TECHNOLOGIES</span>
              <div className="flex items-center gap-1.5 mt-0.5">
                <span className="inline-block w-1.5 h-1.5 rounded-full bg-[#d4af37]"></span>
                <span className="text-[11px] font-semibold text-[#d4af37] uppercase tracking-wider">{portalName}</span>
              </div>
            </div>
          </div>
          {portalBadge && (
            <div className="mt-3 px-2 py-1 rounded bg-[#1c1c1c] border border-[#2a2a2a] text-[11px] text-zinc-400">
              {portalBadge}
            </div>
          )}
        </div>

        {/* Navigation Items */}
        <div className="flex-1 overflow-y-auto px-3 py-4 space-y-6">
          {navSections.map((section, idx) => (
            <div key={idx} className="space-y-1">
              {section.title && (
                <p className="px-3 text-[10px] font-bold uppercase tracking-wider text-zinc-500 mb-2">
                  {section.title}
                </p>
              )}
              {section.items.map((item) => {
                const isActive = pathname === item.path || (item.path !== '/' && pathname.startsWith(item.path + '/'));
                return (
                  <Link
                    key={item.path}
                    href={item.path}
                    onClick={() => setMobileMenuOpen(false)}
                    className={`
                      flex items-center justify-between px-3 py-2 rounded-lg text-xs font-medium transition-all group
                      ${isActive
                        ? 'bg-[#d4af37]/15 text-[#d4af37] border-l-2 border-[#d4af37]'
                        : 'text-zinc-400 hover:text-white hover:bg-white/5'}
                    `}
                  >
                    <div className="flex items-center gap-2.5">
                      {item.icon && <span className={`text-base ${isActive ? 'text-[#d4af37]' : 'text-zinc-400 group-hover:text-zinc-200'}`}>{item.icon}</span>}
                      <span>{item.label}</span>
                    </div>
                    {item.badge && (
                      <span className="text-[10px] font-semibold px-1.5 py-0.5 rounded bg-[#2a2a2a] text-zinc-300">
                        {item.badge}
                      </span>
                    )}
                  </Link>
                );
              })}
            </div>
          ))}
        </div>

        {/* User Card & Logout */}
        <div className="p-4 border-t border-[#2a2a2a] bg-[#0e0e0e]/80">
          <div className="flex items-center justify-between mb-3">
            <div className="flex items-center gap-2.5 min-w-0">
              <div className="w-8 h-8 rounded-full bg-[#202020] border border-[#2a2a2a] flex items-center justify-center text-xs font-bold text-[#d4af37] shrink-0">
                {user?.name ? user.name.slice(0, 2).toUpperCase() : 'U'}
              </div>
              <div className="min-w-0">
                <p className="text-xs font-semibold text-white truncate">{user?.name || 'Authorized User'}</p>
                <p className="text-[10px] text-zinc-500 truncate capitalize">{user?.role || 'Verified'}</p>
              </div>
            </div>
          </div>
          <button
            onClick={handleLogout}
            className="w-full flex items-center justify-center gap-2 px-3 py-2 text-xs font-medium text-zinc-400 hover:text-rose-400 hover:bg-rose-500/10 rounded-lg transition-colors border border-transparent hover:border-rose-500/20"
          >
            <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
            </svg>
            <span>Sign Out</span>
          </button>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 min-w-0 overflow-y-auto bg-[#0a0a0a]">
        <div className="max-w-7xl mx-auto p-4 md:p-8">
          {children}
        </div>
      </main>
    </div>
  );
}

"use client";
import { createContext, useContext, useEffect, useMemo, useState } from 'react';
import { supabase } from '../lib/supabase.js';
import { login as loginApi, register as registerApi, logout as logoutApi } from '../api/auth.js';

/**
 * @typedef {Object} AuthUser
 * @property {string} [id]
 * @property {string} [name]
 * @property {string} [email]
 * @property {string} [role]
 */

/**
 * @typedef {Object} AuthContextValue
 * @property {AuthUser | null} user
 * @property {string | null} accessToken
 * @property {boolean} isAuthenticated
 * @property {boolean} initializing
 * @property {(email: string, password: string) => Promise<AuthUser>} login
 * @property {() => Promise<void>} logout
 * @property {(name: string, email: string, password: string) => Promise<void>} register
 */

/**
 * Explicit contract for legacy portal shells. The mounted provider for the
 * App Router portals is `auth/auth.context.tsx`; this context is retained for
 * the legacy .jsx portal components and is typed here so TypeScript consumers
 * (PortalLayout, ProtectedRoute) get `AuthContextValue` instead of `never`.
 * @type {import('react').Context<AuthContextValue | null>}
 */
const AuthContext = createContext(null);

export function AuthProvider({ children }) {
  const [session, setSession] = useState(null);
  const [user, setUser] = useState(null);
  const [initializing, setInitializing] = useState(true);

  // Initialize auth state on mount
  useEffect(() => {
    async function initAuth() {
      try {
        // First check localStorage for persisted user
        const storedUser = localStorage.getItem('vpd_user');
        const storedToken = localStorage.getItem('vpd_access_token');
        if (storedUser && storedToken) {
          try {
            setUser(JSON.parse(storedUser));
            setSession({ access_token: storedToken });
          } catch {
            // invalid JSON
          }
        }

        // Also check Supabase session if present
        const { data: { session: s } } = await supabase.auth.getSession();
        if (s) {
          setSession(s);
          if (!storedUser) {
            setUser(s.user);
          }
        }
      } catch (err) {
        console.warn('Auth initialization check:', err);
      } finally {
        setInitializing(false);
      }
    }

    initAuth();

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, s) => {
      if (s) {
        setSession(s);
      }
    });

    return () => subscription?.unsubscribe();
  }, []);

  const login = async (email, password) => {
    // FastAPI is the single source of truth for authentication. There is no
    // direct-database or Supabase fallback: only the six accounts listed in
    // docs/credentials.md, with the correct password, can establish a session.
    const response = await loginApi(email, password);
    const tokenData = response?.data;
    if (!tokenData?.user) {
      throw new Error('Invalid email or password.');
    }
    const u = tokenData.user;
    const token = tokenData.access_token || 'vpd_session_token';
    localStorage.setItem('vpd_user', JSON.stringify(u));
    localStorage.setItem('vpd_access_token', token);
    setUser(u);
    setSession({ access_token: token });
    return u;
  };

  const register = async (name, email, password) => {
    // Backend-only registration: if the API rejects it, no local session is
    // created — an account that cannot log in must not look logged in.
    await registerApi(name, email, password);
  };

  const logout = async () => {
    const token = session?.access_token;
    localStorage.removeItem('vpd_user');
    localStorage.removeItem('vpd_access_token');
    setUser(null);
    setSession(null);
    try {
      await supabase.auth.signOut();
    } catch {
      // Best-effort: the local session is already cleared above.
    }
    if (token) {
      try {
        await logoutApi(token);
      } catch {
        // Best-effort server-side revocation; never block logout on it.
      }
    }
  };

  const value = useMemo(
    () => ({
      user,
      accessToken: session?.access_token ?? null,
      isAuthenticated: Boolean(user),
      initializing,
      login,
      logout,
      register,
    }),
    [user, session, initializing]
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

/**
 * Safe outside a mounted provider: returns an anonymous, signed-out value so
 * legacy shells degrade to guest rendering instead of throwing.
 * @returns {AuthContextValue}
 */
export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) {
    return {
      user: null,
      accessToken: null,
      isAuthenticated: false,
      initializing: false,
      login: async () => null,
      logout: async () => {},
      register: async () => null,
    };
  }
  return ctx;
}

import { useEffect, useState } from 'react';

/**
 * @param {() => Promise<{data: any[]}>} fetchFn  API call returning the backend envelope
 * @param {(item: any) => any} adapt               maps one backend record to the shape components expect
 * @param {any[]} fallbackData                      already-adapted demo data, used on error or empty results
 * @param {any[]} deps                               effect dependencies (e.g. active filter)
 */
export default function useApiResource(fetchFn, adapt, fallbackData, deps = []) {
  const [state, setState] = useState({
    items: fallbackData,
    loading: true,
    error: null,
    isFallback: true,
  });

  useEffect(() => {
    let cancelled = false;
    setState((prev) => ({ ...prev, loading: true, error: null }));

    fetchFn()
      .then((payload) => {
        if (cancelled) return;
        const records = payload?.data ?? [];
        if (records.length === 0) {
          setState({ items: fallbackData, loading: false, error: null, isFallback: true });
        } else {
          setState({ items: records.map(adapt), loading: false, error: null, isFallback: false });
        }
      })
      .catch((error) => {
        if (cancelled) return;
        // eslint-disable-next-line no-console
        console.warn('[VPD] Falling back to demo data:', error.message);
        setState({ items: fallbackData, loading: false, error, isFallback: true });
      });

    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);

  return state;
}

"use client";
import React, { useState, useEffect } from 'react';
import PortalLayout from '../../components/portal-shared/PortalLayout';
import { Card, MetricCard, StatusBadge, Button, LoadingSkeleton, EmptyState, Modal } from '../../components/portal-shared/SharedComponents';
import { supabaseRest } from '../../api/supabaseClient.js';

export default function AdminPortal() {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [loading, setLoading] = useState(true);

  // Live state from Supabase / Backend
  const [employees, setEmployees] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [projects, setProjects] = useState([]);
  const [tasks, setTasks] = useState([]);
  const [invoices, setInvoices] = useState([]);
  const [leaves, setLeaves] = useState([]);
  const [auditLogs, setAuditLogs] = useState([]);

  // Modals & form state
  const [modalOpen, setModalOpen] = useState(false);
  const [modalType, setModalType] = useState('');
  const [formLoading, setFormLoading] = useState(false);
  const [formError, setFormError] = useState('');

  // New Employee Form
  const [newEmployee, setNewEmployee] = useState({
    name: '',
    email: '',
    role: 'developer',
    department_id: '',
    designation: 'Software Engineer',
  });

  // New Department Form
  const [newDept, setNewDept] = useState({ name: '', description: '' });

  // New Invoice Form (Finance)
  const [newInvoice, setNewInvoice] = useState({
    invoice_number: `INV-${Date.now().toString().slice(-5)}`,
    amount: 15000,
    status: 'draft',
    due_date: new Date(Date.now() + 30*86400000).toISOString().split('T')[0],
  });

  const loadData = async () => {
    setLoading(true);
    try {
      const [empRes, deptRes, projRes, taskRes, invRes, leaveRes, logRes] = await Promise.all([
        supabaseRest('employees', { query: '?select=*,user:users(*)&limit=50' }).catch(() => []),
        supabaseRest('departments', { query: '?select=*&limit=50' }).catch(() => []),
        supabaseRest('projects', { query: '?select=*&limit=50' }).catch(() => []),
        supabaseRest('tasks', { query: '?select=*&limit=50' }).catch(() => []),
        supabaseRest('invoices', { query: '?select=*&limit=50' }).catch(() => []),
        supabaseRest('leaves', { query: '?select=*&limit=50' }).catch(() => []),
        supabaseRest('audit_logs', { query: '?select=*&order=created_at.desc&limit=20' }).catch(() => []),
      ]);

      setEmployees(empRes || []);
      setDepartments(deptRes || []);
      setProjects(projRes || []);
      setTasks(taskRes || []);
      setInvoices(invRes || []);
      setLeaves(leaveRes || []);
      setAuditLogs(logRes || []);
    } catch (err) {
      console.error('Failed to load admin portal records:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleCreateEmployee = async (e) => {
    e.preventDefault();
    setFormLoading(true);
    setFormError('');
    try {
      // 1. Create user
      const userRes = await supabaseRest('users', {
        method: 'POST',
        body: {
          name: newEmployee.name,
          email: newEmployee.email,
          role: newEmployee.role,
          is_active: true,
          is_email_verified: true,
        },
      });

      const createdUser = userRes?.[0];
      if (createdUser?.id) {
        // 2. Create employee row
        await supabaseRest('employees', {
          method: 'POST',
          body: {
            user_id: createdUser.id,
            employee_code: `EMP-${Math.floor(100 + Math.random() * 900)}`,
            designation: newEmployee.designation,
            department_id: newEmployee.department_id || null,
          },
        });
      }

      setModalOpen(false);
      await loadData();
    } catch (err) {
      setFormError(err.message || 'Failed to create employee');
    } finally {
      setFormLoading(false);
    }
  };

  const handleCreateDepartment = async (e) => {
    e.preventDefault();
    setFormLoading(true);
    setFormError('');
    try {
      await supabaseRest('departments', {
        method: 'POST',
        body: newDept,
      });
      setModalOpen(false);
      await loadData();
    } catch (err) {
      setFormError(err.message || 'Failed to create department');
    } finally {
      setFormLoading(false);
    }
  };

  const handleCreateInvoice = async (e) => {
    e.preventDefault();
    setFormLoading(true);
    setFormError('');
    try {
      await supabaseRest('invoices', {
        method: 'POST',
        body: newInvoice,
      });
      setModalOpen(false);
      await loadData();
    } catch (err) {
      setFormError(err.message || 'Failed to create invoice');
    } finally {
      setFormLoading(false);
    }
  };

  const handleLeaveDecision = async (leaveId, decision) => {
    try {
      await supabaseRest('leaves', {
        method: 'PATCH',
        query: `?id=eq.${leaveId}`,
        body: { status: decision },
      });
      await loadData();
    } catch (err) {
      alert(`Error updating leave: ${err.message}`);
    }
  };

  const navSections = [
    {
      title: 'Governance',
      items: [
        { label: 'Admin Dashboard', path: '/admin', icon: '📊' },
        { label: 'Employees', path: '#employees', icon: '👥', badge: employees.length },
        { label: 'Departments', path: '#departments', icon: '🏢', badge: departments.length },
      ],
    },
    {
      title: 'Operations',
      items: [
        { label: 'Projects & Tasks', path: '#projects', icon: '📁', badge: projects.length },
        { label: 'Leave Requests', path: '#leaves', icon: '🏖️', badge: leaves.filter(l => l.status === 'pending').length },
      ],
    },
    {
      title: 'Finance & System',
      items: [
        { label: 'Finance (Restricted)', path: '#finance', icon: '💳', badge: `$${invoices.reduce((a, b) => a + Number(b.amount || 0), 0).toLocaleString()}` },
        { label: 'Audit Logs', path: '#audit', icon: '🛡️', badge: auditLogs.length },
      ],
    },
  ];

  return (
    <PortalLayout portalName="Admin Portal" portalBadge="Super Admin / Executive" navSections={navSections}>
      {/* Top Banner / Actions */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-white">Administration Workspace</h1>
          <p className="text-xs text-zinc-400 mt-1">Unified governance, workforce management, auditability, and finance.</p>
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={loadData}
            icon={<span>🔄</span>}
          >
            Refresh
          </Button>
          <Button
            variant="gold"
            size="sm"
            onClick={() => { setModalType('employee'); setModalOpen(true); }}
            icon={<span>+</span>}
          >
            Add Employee
          </Button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-[#2a2a2a] mb-6 overflow-x-auto gap-2">
        {['dashboard', 'employees', 'departments', 'projects', 'leaves', 'finance', 'audit'].map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-4 py-2.5 text-xs font-semibold capitalize whitespace-nowrap border-b-2 transition-colors ${
              activeTab === tab
                ? 'border-[#d4af37] text-[#d4af37]'
                : 'border-transparent text-zinc-400 hover:text-white'
            }`}
          >
            {tab === 'finance' ? 'Finance (Restricted)' : tab}
          </button>
        ))}
      </div>

      {loading ? (
        <LoadingSkeleton count={4} height="h-28" />
      ) : (
        <>
          {/* TAB 1: DASHBOARD / OVERVIEW */}
          {activeTab === 'dashboard' && (
            <div className="space-y-6">
              {/* Metrics Row (Dashboard Only) */}
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                <MetricCard
                  label="Total Employees"
                  value={employees.length}
                  trend="up"
                  change="+100% active"
                  icon={<span>👥</span>}
                />
                <MetricCard
                  label="Active Projects"
                  value={projects.length}
                  trend="neutral"
                  change={`${tasks.length} tasks`}
                  icon={<span>📁</span>}
                />
                <MetricCard
                  label="Pending Leaves"
                  value={leaves.filter(l => l.status === 'pending').length}
                  trend={leaves.filter(l => l.status === 'pending').length > 0 ? 'down' : 'up'}
                  change="Awaiting action"
                  icon={<span>⏳</span>}
                />
                <MetricCard
                  label="Total Invoiced"
                  value={`$${invoices.reduce((a, b) => a + Number(b.amount || 0), 0).toLocaleString()}`}
                  trend="up"
                  change={`${invoices.length} billing items`}
                  icon={<span>💰</span>}
                />
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                <Card title="Recent Workforce Additions" subtitle="Latest employee profiles registered in VPD">
                  <div className="space-y-3">
                    {employees.slice(0, 5).map((emp) => (
                      <div key={emp.id} className="flex items-center justify-between p-2.5 rounded-lg bg-[#141414] border border-[#2a2a2a]">
                        <div className="flex items-center gap-3">
                          <div className="w-8 h-8 rounded-full bg-[#222] border border-[#333] flex items-center justify-center font-bold text-xs text-[#d4af37]">
                            {(emp.user?.name || emp.employee_code || 'E').slice(0, 2).toUpperCase()}
                          </div>
                          <div>
                            <p className="text-xs font-semibold text-white">{emp.user?.name || emp.employee_code}</p>
                            <p className="text-[11px] text-zinc-400">{emp.designation || 'Staff'} • {emp.user?.email || 'N/A'}</p>
                          </div>
                        </div>
                        <StatusBadge status={emp.status || 'active'} />
                      </div>
                    ))}
                  </div>
                </Card>

                <Card title="Active Operational Projects" subtitle="Live delivery and client projects">
                  <div className="space-y-3">
                    {projects.slice(0, 5).map((proj) => (
                      <div key={proj.id} className="flex items-center justify-between p-2.5 rounded-lg bg-[#141414] border border-[#2a2a2a]">
                        <div>
                          <p className="text-xs font-semibold text-white">{proj.name}</p>
                          <p className="text-[11px] text-zinc-400">Budget: ${Number(proj.budget || 0).toLocaleString()} • Progress: {proj.progress || 0}%</p>
                        </div>
                        <StatusBadge status={proj.status || 'in progress'} />
                      </div>
                    ))}
                  </div>
                </Card>
              </div>
            </div>
          )}

          {/* TAB 2: EMPLOYEES */}
          {activeTab === 'employees' && (
            <Card
              title="Employee Management Directory"
              subtitle={`Total of ${employees.length} personnel profiles recorded`}
              action={
                <Button size="sm" variant="gold" onClick={() => { setModalType('employee'); setModalOpen(true); }}>
                  + Add Employee
                </Button>
              }
            >
              <div className="overflow-x-auto">
                <table className="w-full text-left text-xs">
                  <thead className="bg-[#121212] text-zinc-400 uppercase text-[10px] tracking-wider border-b border-[#2a2a2a]">
                    <tr>
                      <th className="py-3 px-4">Employee</th>
                      <th className="py-3 px-4">Code</th>
                      <th className="py-3 px-4">Designation</th>
                      <th className="py-3 px-4">Role</th>
                      <th className="py-3 px-4">Status</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[#2a2a2a]">
                    {employees.map((emp) => (
                      <tr key={emp.id} className="hover:bg-white/[0.02]">
                        <td className="py-3 px-4">
                          <div className="font-semibold text-white">{emp.user?.name || 'Personnel'}</div>
                          <div className="text-[11px] text-zinc-400">{emp.user?.email}</div>
                        </td>
                        <td className="py-3 px-4 font-mono text-zinc-300">{emp.employee_code}</td>
                        <td className="py-3 px-4 text-zinc-300">{emp.designation || 'Staff'}</td>
                        <td className="py-3 px-4 capitalize text-[#d4af37] font-medium">{emp.user?.role || 'employee'}</td>
                        <td className="py-3 px-4"><StatusBadge status={emp.status || 'active'} /></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </Card>
          )}

          {/* TAB 3: DEPARTMENTS */}
          {activeTab === 'departments' && (
            <Card
              title="Departments"
              subtitle="Organizational business units"
              action={
                <Button size="sm" variant="gold" onClick={() => { setModalType('department'); setModalOpen(true); }}>
                  + Add Department
                </Button>
              }
            >
              <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
                {departments.map((dept) => (
                  <div key={dept.id} className="p-4 rounded-xl bg-[#141414] border border-[#2a2a2a]">
                    <div className="flex items-center justify-between mb-2">
                      <h4 className="font-semibold text-white text-sm">{dept.name}</h4>
                      <span className="text-[10px] text-[#d4af37] bg-[#d4af37]/10 px-2 py-0.5 rounded-full border border-[#d4af37]/20">Active</span>
                    </div>
                    <p className="text-xs text-zinc-400">{dept.description || 'Enterprise department unit.'}</p>
                  </div>
                ))}
              </div>
            </Card>
          )}

          {/* TAB 4: PROJECTS */}
          {activeTab === 'projects' && (
            <Card title="Projects & Tasks" subtitle="Global project tracking">
              <div className="overflow-x-auto">
                <table className="w-full text-left text-xs">
                  <thead className="bg-[#121212] text-zinc-400 uppercase text-[10px] tracking-wider border-b border-[#2a2a2a]">
                    <tr>
                      <th className="py-3 px-4">Project</th>
                      <th className="py-3 px-4">Progress</th>
                      <th className="py-3 px-4">Budget</th>
                      <th className="py-3 px-4">Status</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[#2a2a2a]">
                    {projects.map((p) => (
                      <tr key={p.id} className="hover:bg-white/[0.02]">
                        <td className="py-3 px-4 font-semibold text-white">{p.name}</td>
                        <td className="py-3 px-4">
                          <div className="w-24 bg-[#222] rounded-full h-1.5 overflow-hidden">
                            <div className="bg-[#d4af37] h-full" style={{ width: `${p.progress || 0}%` }}></div>
                          </div>
                          <span className="text-[10px] text-zinc-400 mt-0.5 block">{p.progress || 0}%</span>
                        </td>
                        <td className="py-3 px-4 font-mono text-zinc-300">${Number(p.budget || 0).toLocaleString()}</td>
                        <td className="py-3 px-4"><StatusBadge status={p.status || 'in progress'} /></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </Card>
          )}

          {/* TAB 5: LEAVES */}
          {activeTab === 'leaves' && (
            <Card title="Employee Leave Approvals" subtitle="Review leave requests submitted by workforce members">
              {leaves.length === 0 ? (
                <EmptyState title="No Leave Requests" message="There are currently no leave requests awaiting action." />
              ) : (
                <div className="overflow-x-auto">
                  <table className="w-full text-left text-xs">
                    <thead className="bg-[#121212] text-zinc-400 uppercase text-[10px] tracking-wider border-b border-[#2a2a2a]">
                      <tr>
                        <th className="py-3 px-4">Type</th>
                        <th className="py-3 px-4">Dates</th>
                        <th className="py-3 px-4">Reason</th>
                        <th className="py-3 px-4">Status</th>
                        <th className="py-3 px-4 text-right">Actions</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-[#2a2a2a]">
                      {leaves.map((l) => (
                        <tr key={l.id} className="hover:bg-white/[0.02]">
                          <td className="py-3 px-4 capitalize font-semibold text-white">{l.leave_type || 'Casual'}</td>
                          <td className="py-3 px-4 text-zinc-300">{l.start_date} to {l.end_date}</td>
                          <td className="py-3 px-4 text-zinc-400 max-w-xs truncate">{l.reason || 'Personal leave'}</td>
                          <td className="py-3 px-4"><StatusBadge status={l.status} /></td>
                          <td className="py-3 px-4 text-right space-x-2">
                            {l.status === 'pending' && (
                              <>
                                <button
                                  onClick={() => handleLeaveDecision(l.id, 'approved')}
                                  className="text-[11px] px-2.5 py-1 rounded bg-emerald-500/20 text-emerald-400 hover:bg-emerald-500/30"
                                >
                                  Approve
                                </button>
                                <button
                                  onClick={() => handleLeaveDecision(l.id, 'rejected')}
                                  className="text-[11px] px-2.5 py-1 rounded bg-rose-500/20 text-rose-400 hover:bg-rose-500/30"
                                >
                                  Reject
                                </button>
                              </>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </Card>
          )}

          {/* TAB 6: FINANCE (RESTRICTED) */}
          {activeTab === 'finance' && (
            <Card
              title="Finance Module (Restricted)"
              subtitle="Protected enterprise billing, invoices, and revenue records"
              action={
                <Button size="sm" variant="gold" onClick={() => { setModalType('invoice'); setModalOpen(true); }}>
                  + Issue Invoice
                </Button>
              }
            >
              <div className="overflow-x-auto">
                <table className="w-full text-left text-xs">
                  <thead className="bg-[#121212] text-zinc-400 uppercase text-[10px] tracking-wider border-b border-[#2a2a2a]">
                    <tr>
                      <th className="py-3 px-4">Invoice #</th>
                      <th className="py-3 px-4">Amount</th>
                      <th className="py-3 px-4">Due Date</th>
                      <th className="py-3 px-4">Status</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[#2a2a2a]">
                    {invoices.map((inv) => (
                      <tr key={inv.id} className="hover:bg-white/[0.02]">
                        <td className="py-3 px-4 font-mono font-semibold text-white">{inv.invoice_number}</td>
                        <td className="py-3 px-4 font-mono text-[#d4af37] font-bold">${Number(inv.amount || 0).toLocaleString()}</td>
                        <td className="py-3 px-4 text-zinc-400">{inv.due_date || 'N/A'}</td>
                        <td className="py-3 px-4"><StatusBadge status={inv.status} /></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </Card>
          )}

          {/* TAB 7: AUDIT LOGS */}
          {activeTab === 'audit' && (
            <Card title="Security & Activity Audit Trail" subtitle="System records and user action tracking">
              <div className="overflow-x-auto">
                <table className="w-full text-left text-xs">
                  <thead className="bg-[#121212] text-zinc-400 uppercase text-[10px] tracking-wider border-b border-[#2a2a2a]">
                    <tr>
                      <th className="py-3 px-4">Action</th>
                      <th className="py-3 px-4">Entity Type</th>
                      <th className="py-3 px-4">IP Address</th>
                      <th className="py-3 px-4">Timestamp</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[#2a2a2a]">
                    {auditLogs.map((log) => (
                      <tr key={log.id} className="hover:bg-white/[0.02]">
                        <td className="py-3 px-4 font-semibold text-zinc-200">{log.action}</td>
                        <td className="py-3 px-4 text-zinc-400">{log.entity_type || 'System'}</td>
                        <td className="py-3 px-4 font-mono text-zinc-500">{log.ip_address || '127.0.0.1'}</td>
                        <td className="py-3 px-4 text-zinc-500">{new Date(log.created_at).toLocaleString()}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </Card>
          )}
        </>
      )}

      {/* CREATE MODAL */}
      <Modal
        isOpen={modalOpen}
        onClose={() => setModalOpen(false)}
        title={
          modalType === 'employee' ? 'Add New Employee' :
          modalType === 'department' ? 'Create Department' : 'Issue New Invoice'
        }
      >
        {formError && (
          <div className="mb-4 p-2.5 rounded bg-rose-500/10 border border-rose-500/30 text-rose-300 text-xs">
            {formError}
          </div>
        )}

        {modalType === 'employee' && (
          <form onSubmit={handleCreateEmployee} className="space-y-4">
            <div>
              <label className="block text-xs font-medium text-zinc-300 mb-1">Full Name</label>
              <input
                required
                type="text"
                value={newEmployee.name}
                onChange={(e) => setNewEmployee({ ...newEmployee, name: e.target.value })}
                className="w-full px-3 py-2 bg-[#121212] border border-[#2a2a2a] rounded-lg text-xs text-white focus:outline-none focus:border-[#d4af37]"
                placeholder="Jane Doe"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-zinc-300 mb-1">Corporate Email</label>
              <input
                required
                type="email"
                value={newEmployee.email}
                onChange={(e) => setNewEmployee({ ...newEmployee, email: e.target.value })}
                className="w-full px-3 py-2 bg-[#121212] border border-[#2a2a2a] rounded-lg text-xs text-white focus:outline-none focus:border-[#d4af37]"
                placeholder="jane.doe@vpdtechnologies.com"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-zinc-300 mb-1">Designation</label>
              <input
                type="text"
                value={newEmployee.designation}
                onChange={(e) => setNewEmployee({ ...newEmployee, designation: e.target.value })}
                className="w-full px-3 py-2 bg-[#121212] border border-[#2a2a2a] rounded-lg text-xs text-white focus:outline-none focus:border-[#d4af37]"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-zinc-300 mb-1">Department</label>
              <select
                value={newEmployee.department_id}
                onChange={(e) => setNewEmployee({ ...newEmployee, department_id: e.target.value })}
                className="w-full px-3 py-2 bg-[#121212] border border-[#2a2a2a] rounded-lg text-xs text-white focus:outline-none focus:border-[#d4af37]"
              >
                <option value="">Select Department</option>
                {departments.map((d) => (
                  <option key={d.id} value={d.id}>{d.name}</option>
                ))}
              </select>
            </div>
            <Button type="submit" variant="gold" loading={formLoading} className="w-full py-2">
              Create Employee Profile
            </Button>
          </form>
        )}

        {modalType === 'department' && (
          <form onSubmit={handleCreateDepartment} className="space-y-4">
            <div>
              <label className="block text-xs font-medium text-zinc-300 mb-1">Department Name</label>
              <input
                required
                type="text"
                value={newDept.name}
                onChange={(e) => setNewDept({ ...newDept, name: e.target.value })}
                className="w-full px-3 py-2 bg-[#121212] border border-[#2a2a2a] rounded-lg text-xs text-white focus:outline-none focus:border-[#d4af37]"
                placeholder="e.g. Artificial Intelligence"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-zinc-300 mb-1">Description</label>
              <textarea
                value={newDept.description}
                onChange={(e) => setNewDept({ ...newDept, description: e.target.value })}
                className="w-full px-3 py-2 bg-[#121212] border border-[#2a2a2a] rounded-lg text-xs text-white focus:outline-none focus:border-[#d4af37]"
                rows={3}
              />
            </div>
            <Button type="submit" variant="gold" loading={formLoading} className="w-full py-2">
              Save Department
            </Button>
          </form>
        )}

        {modalType === 'invoice' && (
          <form onSubmit={handleCreateInvoice} className="space-y-4">
            <div>
              <label className="block text-xs font-medium text-zinc-300 mb-1">Invoice Number</label>
              <input
                required
                type="text"
                value={newInvoice.invoice_number}
                onChange={(e) => setNewInvoice({ ...newInvoice, invoice_number: e.target.value })}
                className="w-full px-3 py-2 bg-[#121212] border border-[#2a2a2a] rounded-lg text-xs text-white focus:outline-none focus:border-[#d4af37]"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-zinc-300 mb-1">Amount (USD)</label>
              <input
                required
                type="number"
                value={newInvoice.amount}
                onChange={(e) => setNewInvoice({ ...newInvoice, amount: Number(e.target.value) })}
                className="w-full px-3 py-2 bg-[#121212] border border-[#2a2a2a] rounded-lg text-xs text-white focus:outline-none focus:border-[#d4af37]"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-zinc-300 mb-1">Due Date</label>
              <input
                required
                type="date"
                value={newInvoice.due_date}
                onChange={(e) => setNewInvoice({ ...newInvoice, due_date: e.target.value })}
                className="w-full px-3 py-2 bg-[#121212] border border-[#2a2a2a] rounded-lg text-xs text-white focus:outline-none focus:border-[#d4af37]"
              />
            </div>
            <Button type="submit" variant="gold" loading={formLoading} className="w-full py-2">
              Issue Invoice
            </Button>
          </form>
        )}
      </Modal>
    </PortalLayout>
  );
}

