      </div>
    </div>
  );
};

export default Finance;

"use client";
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useRouter, usePathname } from 'next/navigation';
import { departmentsApi, usersApi } from '../../../../api';
import { useAuth } from '../../../../auth/auth.context';
import { useNotifications } from '../../../../app/providers/NotificationProvider';
import DataTable, { Column, SortState } from '../../../../shared/components/DataTable';
import StatusBadge from '../../../../shared/components/StatusBadge';
import Button from '../../../../shared/components/Button';
import PageContainer from '../../../../shared/components/PageContainer';
import PageHeader from '../../../../shared/components/PageHeader';
import Modal from '../../../../shared/components/Modal';
import Input from '../../../../shared/components/Input';
import Select from '../../../../shared/components/Select';
import ErrorState from '../../../../shared/components/ErrorState';
import ConfirmDialog from '../../../../shared/components/ConfirmDialog';
import Pagination from '../../../../shared/components/Pagination';
import { BulkUserAction, BulkActionResult, UserListItem } from '../../../../types/user.types';

const ROLE_OPTIONS = [
  { value: 'super_admin', label: 'Super Admin' },
  { value: 'admin', label: 'Admin' },
  { value: 'hr', label: 'HR' },
  { value: 'finance', label: 'Finance' },
  { value: 'sales', label: 'Sales' },
  { value: 'marketing', label: 'Marketing' },
  { value: 'project_manager', label: 'Project Manager' },
  { value: 'developer', label: 'Developer' },
  { value: 'qa', label: 'QA' },
  { value: 'support', label: 'Support' },
  { value: 'employee', label: 'Employee' },
  { value: 'client', label: 'Client' },
  { value: 'guest', label: 'Guest' },
  { value: 'partner', label: 'Partner' },
];

const STATUS_FILTER_OPTIONS = [
  { value: '', label: 'All Statuses' },
  { value: 'active', label: 'Active' },
  { value: 'inactive', label: 'Inactive' },
  { value: 'suspended', label: 'Suspended' },
  { value: 'locked', label: 'Locked' },
  { value: 'pending', label: 'Pending' },
];

/** Raw is_active flag — distinct from the derived status filter. */
const ACCOUNT_STATE_OPTIONS = [
  { value: '', label: 'All Account States' },
  { value: 'true', label: 'Enabled' },
  { value: 'false', label: 'Disabled' },
];

const PRIVILEGED_ROLES = ['admin', 'super_admin'];

/** Mirrors backend EMPLOYEE_ROLES — only these get an Employee profile,
 * so designation/department inputs are only shown for them. */
const EMPLOYEE_ROLES = new Set([
  'employee',
  'developer',
  'sales',
  'marketing',
  'project_manager',
  'qa',
  'support',
  'finance',
  'hr',
  'admin',
  'super_admin',
]);

type SingleAction = 'deactivate' | 'activate' | 'suspend' | 'restore' | 'unlock';

const ACTION_COPY: Record<
  SingleAction,
  { verb: string; past: string; description: string; variant: 'danger' | 'primary' }
> = {
  deactivate: {
    verb: 'Deactivate',
    past: 'deactivated',
    description:
      'will lose access immediately and all active sessions will be revoked. The account keeps its data and can be reactivated at any time.',
    variant: 'danger',
  },
  activate: {
    verb: 'Activate',
    past: 'activated',
    description: 'will regain access, and any login lockout will be cleared.',
    variant: 'primary',
  },
  suspend: {
    verb: 'Suspend',
    past: 'suspended',
    description:
      'will be suspended immediately — access blocked and all active sessions revoked — until the account is restored.',
    variant: 'danger',
  },
  restore: {
    verb: 'Restore',
    past: 'restored',
    description: 'will be restored to active and can sign in again.',
    variant: 'primary',
  },
  unlock: {
    verb: 'Unlock',
    past: 'unlocked',
    description: 'is locked out after failed login attempts; unlocking clears the lockout so they can sign in again.',
    variant: 'primary',
  },
};

type PendingAction =
  | { kind: 'single'; action: SingleAction; user: UserListItem }
  | { kind: 'bulk'; action: BulkUserAction; count: number }
  | null;

interface CreateFormState {
  name: string;
  email: string;
  phone: string;
  role: string;
  designation: string;
  department_id: string;
  passwordMode: 'invite' | 'password';
  password: string;
}

const EMPTY_CREATE_FORM: CreateFormState = {
  name: '',
  email: '',
  phone: '',
  role: 'employee',
  designation: '',
  department_id: '',
  passwordMode: 'invite',
  password: '',
};

function passwordIssue(pw: string): string | null {
  if (pw.length < 6 || pw.length > 128) return 'Password must be between 6 and 128 characters.';
  if (!/[A-Z]/.test(pw)) return 'Password must contain at least one uppercase letter.';
  if (!/[a-z]/.test(pw)) return 'Password must contain at least one lowercase letter.';
  if (!/\d/.test(pw)) return 'Password must contain at least one number.';
  if (!/[^A-Za-z0-9]/.test(pw)) return 'Password must contain at least one special character.';
  return null;
}

function formatDateTime(iso: string | null): string {
  if (!iso) return '—';
  return new Date(iso).toLocaleString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
}

export const Users: React.FC = () => {
  const router = useRouter();
  const pathname = usePathname();
  const { user: me } = useAuth();
  const { showNotification } = useNotifications();

  // Mounted at /admin/users and /hr/users — keep navigation inside the portal
  // the user came from.
  const isHrPortal = pathname?.startsWith('/hr') ?? false;
  const detailBase = isHrPortal ? '/hr/users' : '/admin/users';
  const portalLabel = isHrPortal ? 'HR' : 'Admin';

  const [users, setUsers] = useState<UserListItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<{ status?: number; message: string } | null>(null);
  const [meta, setMeta] = useState<{ total: number; page: number; limit: number; total_pages: number }>({
    total: 0,
    page: 1,
    limit: 10,
    total_pages: 0,
  });

  // Server query state
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);
  const [searchInput, setSearchInput] = useState('');
  const [search, setSearch] = useState('');
  const [roleFilter, setRoleFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [accountStateFilter, setAccountStateFilter] = useState('');
  const [departmentFilter, setDepartmentFilter] = useState('');
  const [designationInput, setDesignationInput] = useState('');
  const [designation, setDesignation] = useState('');
  const [createdFrom, setCreatedFrom] = useState('');
  const [createdTo, setCreatedTo] = useState('');
  const [sortState, setSortState] = useState<SortState | null>({ key: 'created_at', direction: 'desc' });

  // Selection & dialogs
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [pendingAction, setPendingAction] = useState<PendingAction>(null);
  const [actionLoading, setActionLoading] = useState(false);
  const [bulkFailures, setBulkFailures] = useState<BulkActionResult['failed'] | null>(null);

  // Create modal
  const [createOpen, setCreateOpen] = useState(false);
  const [createForm, setCreateForm] = useState<CreateFormState>(EMPTY_CREATE_FORM);
  const [createError, setCreateError] = useState<string | null>(null);
  const [createLoading, setCreateLoading] = useState(false);
  const [departments, setDepartments] = useState<Array<{ id: string; name: string }>>([]);

  const [exporting, setExporting] = useState(false);

  const sortParam = sortState ? (sortState.direction === 'desc' ? `-${sortState.key}` : sortState.key) : undefined;

  const filterParams = useMemo(
    () => ({
      search: search || undefined,
      role: (roleFilter || undefined) as UserListItem['role'] | undefined,
      status: (statusFilter || undefined) as UserListItem['status'] | undefined,
      is_active: accountStateFilter === '' ? undefined : accountStateFilter === 'true',
      department_id: departmentFilter || undefined,
      designation: designation || undefined,
      created_from: createdFrom || undefined,
      created_to: createdTo || undefined,
    }),
    [search, roleFilter, statusFilter, accountStateFilter, departmentFilter, designation, createdFrom, createdTo]
  );

  const filtersActive =
    !!search ||
    !!roleFilter ||
    !!statusFilter ||
    !!accountStateFilter ||
    !!departmentFilter ||
    !!designation ||
    !!createdFrom ||
    !!createdTo;

  const loadUsers = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await usersApi.getAll({ page, limit: pageSize, sort: sortParam, ...filterParams });
      const rows = res.data || [];
      const m = res.meta || {};
      setUsers(rows);
      setMeta({
        total: m.total ?? rows.length,
        page: m.page ?? page,
        limit: m.limit ?? pageSize,
        total_pages: m.total_pages ?? 1,
      });
      if (rows.length === 0 && page > 1 && typeof m.total_pages === 'number' && m.total_pages < page) {
        setPage(Math.max(m.total_pages, 1));
      }
    } catch (err: any) {
      if (err?.status === 403) {
        setError({ status: 403, message: 'You do not have permission to manage users. This module is restricted to Admin and HR roles.' });
      } else {
        setError({ status: err?.status, message: err?.message || 'Failed to load users. Please try again.' });
      }
    } finally {
      setLoading(false);
    }
  }, [page, pageSize, sortParam, filterParams]);

  useEffect(() => {
    loadUsers();
  }, [loadUsers]);

  // Selection is page/filter scoped — clearing avoids surprise cross-page bulk edits.
  useEffect(() => {
    setSelectedIds(new Set());
  }, [
    page,
    pageSize,
    search,
    roleFilter,
    statusFilter,
    accountStateFilter,
    departmentFilter,
    designation,
    createdFrom,
    createdTo,
    sortState,
  ]);

  // Debounced search
  const firstSearchRun = useRef(true);
  useEffect(() => {
    if (firstSearchRun.current) {
      firstSearchRun.current = false;
      return;
    }
    const t = setTimeout(() => {
      setSearch(searchInput.trim());
      setPage(1);
    }, 350);
    return () => clearTimeout(t);
  }, [searchInput]);

  // Debounced designation filter
  const firstDesignationRun = useRef(true);
  useEffect(() => {
    if (firstDesignationRun.current) {
      firstDesignationRun.current = false;
      return;
    }
    const t = setTimeout(() => {
      setDesignation(designationInput.trim());
      setPage(1);
    }, 350);
    return () => clearTimeout(t);
  }, [designationInput]);

  // Departments power both the list filter and the create form — a single
  // fetch on mount serves both.
  useEffect(() => {
    departmentsApi
      .getAll()
      .then((res) => setDepartments(res.data || []))
      .catch(() => setDepartments([]));
  }, []);

  const canManage = (row: UserListItem): boolean =>
    me?.role === 'super_admin' || !PRIVILEGED_ROLES.includes(row.role);

  const isSelf = (row: UserListItem): boolean => !!me && me.id === row.id;

  const quickActionsFor = (row: UserListItem): Array<{ action: SingleAction; label: string; danger?: boolean }> => {
    switch (row.status) {
      case 'active':
      case 'pending':
        return [
          { action: 'deactivate', label: 'Deactivate', danger: true },
          { action: 'suspend', label: 'Suspend', danger: true },
        ];
      case 'inactive':
        return [{ action: 'activate', label: 'Activate' }];
      case 'suspended':
        return [{ action: 'restore', label: 'Restore' }];
      case 'locked':
        return [{ action: 'unlock', label: 'Unlock' }];
      default:
        return [];
    }
  };

  const handleSortChange = (key: string) => {
    setSortState((prev) =>
      prev?.key === key ? { key, direction: prev.direction === 'asc' ? 'desc' : 'asc' } : { key, direction: 'asc' }
    );
    setPage(1);
  };

  const resetFilters = () => {
    setSearchInput('');
    setSearch('');
    setRoleFilter('');
    setStatusFilter('');
    setAccountStateFilter('');
    setDepartmentFilter('');
    setDesignationInput('');
    setDesignation('');
    setCreatedFrom('');
    setCreatedTo('');
    setPage(1);
  };

  const runSingleAction = async (action: SingleAction, target: UserListItem) => {
    setActionLoading(true);
    try {
      if (action === 'deactivate') await usersApi.deactivate(target.id);
      else if (action === 'activate') await usersApi.activate(target.id);
      else if (action === 'suspend') await usersApi.suspend(target.id);
      else if (action === 'restore') await usersApi.restore(target.id);
      else if (action === 'unlock') await usersApi.unlock(target.id);
      showNotification('success', `${target.name} has been ${ACTION_COPY[action].past}.`);
      setPendingAction(null);
      await loadUsers();
    } catch (err: any) {
      showNotification('error', err?.message || `Failed to ${ACTION_COPY[action].verb.toLowerCase()} this user.`);
    } finally {
      setActionLoading(false);
    }
  };

  const runBulkAction = async (action: BulkUserAction) => {
    setActionLoading(true);
    try {
      const res = await usersApi.bulkAction(action, Array.from(selectedIds));
      const { succeeded, failed } = res.data;
      const total = succeeded.length + failed.length;
      if (failed.length === 0) {
        showNotification('success', `${succeeded.length} user${succeeded.length === 1 ? '' : 's'} ${ACTION_COPY[action].past}.`);
      } else {
        showNotification(
          'warning',
          `${succeeded.length} of ${total} users ${ACTION_COPY[action].past}. ${failed.length} failed — see details.`
        );
        setBulkFailures(failed);
      }
      setSelectedIds(new Set());
      setPendingAction(null);
      await loadUsers();
    } catch (err: any) {
      showNotification('error', err?.message || `Bulk ${action} failed.`);
    } finally {
      setActionLoading(false);
    }
  };

  const handleExport = async () => {
    setExporting(true);
    try {
      const res = await usersApi.exportCsv({ sort: sortParam, ...filterParams });
      if (!res.ok) {
        let message = 'Export failed. Please try again.';
        try {
          const body = await res.json();
          message = body?.message || message;
        } catch {
          /* non-JSON error body */
        }
        throw new Error(message);
      }
      const blob = await res.blob();
      const disposition = res.headers.get('Content-Disposition') || '';
      const match = /filename="?([^";]+)"?/.exec(disposition);
      const filename = match?.[1] || `vpd-users-${new Date().toISOString().slice(0, 10)}.csv`;
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = filename;
      document.body.appendChild(link);
      link.click();
      link.remove();
      URL.revokeObjectURL(url);
      showNotification('success', 'CSV export downloaded — it matches the current filters.');
    } catch (err: any) {
      showNotification('error', err?.message || 'Export failed. Please try again.');
    } finally {
      setExporting(false);
    }
  };

  const createRoleOptions = useMemo(
    () => (me?.role === 'super_admin' ? ROLE_OPTIONS : ROLE_OPTIONS.filter((o) => !PRIVILEGED_ROLES.includes(o.value))),
    [me?.role]
  );

  const submitCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    setCreateError(null);
    if (!createForm.name.trim()) return setCreateError('Full name is required.');
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(createForm.email.trim())) return setCreateError('A valid email address is required.');
    if (createForm.passwordMode === 'password') {
      const issue = passwordIssue(createForm.password);
      if (issue) return setCreateError(issue);
    }
    const isEmployeeRole = EMPLOYEE_ROLES.has(createForm.role);
    setCreateLoading(true);
    try {
      const res = await usersApi.create({
        name: createForm.name.trim(),
        email: createForm.email.trim(),
        phone: createForm.phone.trim() || undefined,
        role: createForm.role,
        designation: isEmployeeRole && createForm.designation.trim() ? createForm.designation.trim() : undefined,
        department_id: isEmployeeRole && createForm.department_id ? createForm.department_id : undefined,
        password: createForm.passwordMode === 'password' ? createForm.password : undefined,
      });
      const inviteSent = res.data?.invite_sent;
      if (createForm.passwordMode === 'invite' && !inviteSent) {
        showNotification(
          'warning',
          `User created, but the invite email could not be sent (email service not configured). Use "Force password reset" to resend the setup link.`
        );
      } else if (createForm.passwordMode === 'invite') {
        showNotification('success', `User created — an invite email with a password setup link was sent to ${createForm.email.trim()}.`);
      } else {
        showNotification('success', `User created. Share the initial password with ${createForm.name.trim()} through a secure channel.`);
      }
      setCreateOpen(false);
      setCreateForm(EMPTY_CREATE_FORM);
      setPage(1);
      await loadUsers();
    } catch (err: any) {
      setCreateError(err?.message || 'Failed to create user.');
    } finally {
      setCreateLoading(false);
    }
  };

  const selectedUsers = useMemo(() => users.filter((u) => selectedIds.has(u.id)), [users, selectedIds]);

  const confirmCopy = useMemo(() => {
    if (!pendingAction) return null;
    if (pendingAction.kind === 'single') {
      const { action, user } = pendingAction;
      const copy = ACTION_COPY[action];
      return {
        title: `${copy.verb} ${user.name}?`,
        message: (
          <p>
            <strong className="text-white">{user.name}</strong> ({user.email}) {copy.description}
          </p>
        ),
        confirmText: `${copy.verb} User`,
        variant: copy.variant,
        onConfirm: () => runSingleAction(action, user),
      };
    }
    const { action, count } = pendingAction;
    const copy = ACTION_COPY[action];
    return {
      title: `${copy.verb} ${count} selected user${count === 1 ? '' : 's'}?`,
      message: (
        <div className="space-y-2">
          <p>
            All <strong className="text-white">{count}</strong> selected account{count === 1 ? '' : 's'} {copy.description}
          </p>
          <p className="text-xs text-[#A1A1AA]">
            Accounts you cannot manage (Admin/Super Admin, unless you are a Super Admin) or your own account will be
            skipped and reported individually.
          </p>
        </div>
      ),
      confirmText: `${copy.verb} ${count} User${count === 1 ? '' : 's'}`,
      variant: copy.variant,
      onConfirm: () => runBulkAction(action),
    };
  }, [pendingAction, selectedIds, users]);

  const columns: Column<UserListItem>[] = [
    {
      header: 'Name',
      sortKey: 'name',
      accessor: (row) => <span className="font-medium text-white">{row.name}</span>,
    },
    {
      header: 'Email',
      sortKey: 'email',
      accessor: (row) => <span className="text-[#D4D4D8]">{row.email}</span>,
    },
    {
      header: 'Employee ID',
      accessor: (row) => <span className="font-mono text-xs text-[#A1A1AA]">{row.employee_code || '—'}</span>,
    },
    {
      header: 'Role',
      sortKey: 'role',
      accessor: (row) => (
        <StatusBadge status={row.role} variant={PRIVILEGED_ROLES.includes(row.role) ? 'gold' : 'neutral'} />
      ),
    },
    {
      header: 'Department',
      accessor: (row) => <span className="text-xs text-[#D4D4D8]">{row.department_name || '—'}</span>,
    },
    {
      header: 'Status',
      accessor: (row) => (
        <div className="flex flex-col items-start gap-1">
          <StatusBadge status={row.status} />
          {row.status === 'pending' && <span className="text-[10px] text-[#A1A1AA]">invite not accepted</span>}
        </div>
      ),
    },
    {
      header: 'Last Login',
      sortKey: 'last_login_at',
      accessor: (row) => <span className="text-xs text-[#A1A1AA]">{formatDateTime(row.last_login_at)}</span>,
    },
    {
      header: 'Created',
      sortKey: 'created_at',
      accessor: (row) => <span className="text-xs text-[#A1A1AA]">{formatDateTime(row.created_at)}</span>,
    },
    {
      header: 'Actions',
      className: 'text-right',
      accessor: (row) => (
        <div
          className="flex items-center justify-end gap-2 whitespace-nowrap"
          onClick={(e) => e.stopPropagation()}
        >
          <Button variant="ghost" size="sm" onClick={() => router.push(`${detailBase}/${row.id}`)}>
            View
          </Button>
          {isSelf(row) ? (
            <span className="text-[10px] uppercase tracking-wide text-[#A1A1AA]">You</span>
          ) : (
            canManage(row) &&
            quickActionsFor(row).map((qa) => (
              <Button
                key={qa.action}
                variant={qa.danger ? 'danger' : 'secondary'}
                size="sm"
                onClick={() => setPendingAction({ kind: 'single', action: qa.action, user: row })}
              >
                {qa.label}
              </Button>
            ))
          )}
        </div>
      ),
    },
  ];

  if (error) {
    return (
      <PageContainer>
        <PageHeader
          title="Workforce Users"
          description="Create, secure and manage every account across VPD portals"
          breadcrumbs={[{ label: portalLabel }, { label: 'Workforce Users' }]}
        />
        <ErrorState title={error.status === 403 ? 'Access Denied' : 'Something went wrong'} message={error.message} onRetry={loadUsers} />
      </PageContainer>
    );
  }

  return (
    <PageContainer maxWidth="full">
      <PageHeader
        title="Workforce Users"
        description="Create, secure and manage every account across VPD portals"
        breadcrumbs={[{ label: portalLabel }, { label: 'Workforce Users' }]}
        badge={<span className="text-xs text-[#A1A1AA]">{meta.total} account{meta.total === 1 ? '' : 's'}</span>}
        actions={
          <>
            <Button variant="secondary" size="sm" onClick={handleExport} loading={exporting}>
              Export CSV
            </Button>
            <Button variant="primary" size="sm" onClick={() => setCreateOpen(true)}>
              + Add User
            </Button>
          </>
        }
      />

      {/* Filters */}
      <div className="flex flex-col gap-3 rounded-xl border border-[#2A2A2A] bg-[#171717] p-4">
        <div className="flex flex-col gap-3 lg:flex-row lg:items-center">
          <div className="flex-1 min-w-0">
            <Input
              type="search"
              placeholder="Search name, email, phone, or employee code…"
              value={searchInput}
              onChange={(e) => setSearchInput(e.target.value)}
              aria-label="Search users"
            />
          </div>
          <div className="w-full lg:w-48">
            <Select
              value={roleFilter}
              onChange={(e) => {
                setRoleFilter(e.target.value);
                setPage(1);
              }}
              options={[{ value: '', label: 'All Roles' }, ...ROLE_OPTIONS]}
              aria-label="Filter by role"
            />
          </div>
          <div className="w-full lg:w-40">
            <Select
              value={statusFilter}
              onChange={(e) => {
                setStatusFilter(e.target.value);
                setPage(1);
              }}
              options={STATUS_FILTER_OPTIONS}
              aria-label="Filter by status"
            />
          </div>
          <div className="w-full lg:w-44">
            <Select
              value={accountStateFilter}
              onChange={(e) => {
                setAccountStateFilter(e.target.value);
                setPage(1);
              }}
              options={ACCOUNT_STATE_OPTIONS}
              aria-label="Filter by account state"
            />
          </div>
        </div>
        <div className="flex flex-col gap-3 lg:flex-row lg:items-end">
          <div className="w-full lg:w-52">
            <Select
              value={departmentFilter}
              onChange={(e) => {
                setDepartmentFilter(e.target.value);
                setPage(1);
              }}
              options={[
                { value: '', label: 'All Departments' },
                ...departments.map((d) => ({ value: d.id, label: d.name })),
              ]}
              aria-label="Filter by department"
            />
          </div>
          <div className="w-full lg:w-52">
            <Input
              placeholder="Filter by designation…"
              value={designationInput}
              onChange={(e) => setDesignationInput(e.target.value)}
              aria-label="Filter by designation"
            />
          </div>
          <div className="w-full lg:w-44">
            <Input
              type="date"
              label="Created from"
              value={createdFrom}
              max={createdTo || undefined}
              onChange={(e) => {
                setCreatedFrom(e.target.value);
                setPage(1);
              }}
              className="[color-scheme:dark]"
              aria-label="Created from date"
            />
          </div>
          <div className="w-full lg:w-44">
            <Input
              type="date"
              label="Created to"
              value={createdTo}
              min={createdFrom || undefined}
              onChange={(e) => {
                setCreatedTo(e.target.value);
                setPage(1);
              }}
              className="[color-scheme:dark]"
              aria-label="Created to date"
            />
          </div>
          {filtersActive && (
            <div className="flex justify-end lg:ml-auto">
              <Button variant="ghost" size="sm" onClick={resetFilters}>
                Reset filters
              </Button>
            </div>
          )}
        </div>
      </div>

      {/* Bulk action toolbar */}
      {selectedIds.size > 0 && (
        <div className="flex flex-wrap items-center gap-3 rounded-xl border border-[#D4AF37]/30 bg-[#D4AF37]/5 px-4 py-3">
          <span className="text-xs font-semibold text-[#DFC067]">
            {selectedIds.size} user{selectedIds.size === 1 ? '' : 's'} selected
          </span>
          {selectedUsers.length > 0 && (
            <span className="hidden text-[11px] text-[#A1A1AA] lg:inline">
              {selectedUsers
                .slice(0, 3)
                .map((u) => u.name)
                .join(', ')}
              {selectedUsers.length > 3 ? ` +${selectedUsers.length - 3} more` : ''}
            </span>
          )}
          <div className="flex flex-wrap items-center gap-2">
            {(['activate', 'deactivate', 'suspend', 'restore'] as BulkUserAction[]).map((action) => (
              <Button
                key={action}
                variant={action === 'suspend' || action === 'deactivate' ? 'danger' : 'secondary'}
                size="sm"
                onClick={() => setPendingAction({ kind: 'bulk', action, count: selectedIds.size })}
              >
                {ACTION_COPY[action].verb}
              </Button>
            ))}
            <Button variant="ghost" size="sm" onClick={() => setSelectedIds(new Set())}>
              Clear selection
            </Button>
          </div>
        </div>
      )}

      <DataTable
        loading={loading}
        data={users}
        columns={columns}
        sortState={sortState}
        onSortChange={handleSortChange}
        selectable
        selectedIds={selectedIds}
        onSelectionChange={setSelectedIds}
        onRowClick={(row) => router.push(`${detailBase}/${row.id}`)}
        emptyTitle={filtersActive ? 'No Matching Users' : 'No Users Yet'}
        emptyMessage={
          filtersActive
            ? 'No accounts match the current search and filters. Adjust or reset the filters to see more.'
            : 'Create the first workforce account to get started.'
        }
      />

      <Pagination
        currentPage={meta.page}
        totalPages={meta.total_pages}
        onPageChange={setPage}
        totalItems={meta.total}
        pageSize={pageSize}
        onPageSizeChange={(n) => {
          setPageSize(n);
          setPage(1);
        }}
      />

      {/* Create User Modal */}
      <Modal isOpen={createOpen} onClose={() => !createLoading && setCreateOpen(false)} title="Add Workforce Account" maxWidth="lg">
        <form onSubmit={submitCreate} className="space-y-4">
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
            <Input
              label="Full Name"
              value={createForm.name}
              onChange={(e) => setCreateForm({ ...createForm, name: e.target.value })}
              required
            />
            <Input
              label="Email"
              type="email"
              value={createForm.email}
              onChange={(e) => setCreateForm({ ...createForm, email: e.target.value })}
              required
            />
            <Input
              label="Phone (optional)"
              value={createForm.phone}
              onChange={(e) => setCreateForm({ ...createForm, phone: e.target.value })}
            />
            <Select
              label="Role"
              value={createForm.role}
              onChange={(e) => setCreateForm({ ...createForm, role: e.target.value })}
              options={createRoleOptions}
            />
            {EMPLOYEE_ROLES.has(createForm.role) && (
              <>
                <Input
                  label="Designation (optional)"
                  value={createForm.designation}
                  onChange={(e) => setCreateForm({ ...createForm, designation: e.target.value })}
                />
                <Select
                  label="Department (optional)"
                  value={createForm.department_id}
                  onChange={(e) => setCreateForm({ ...createForm, department_id: e.target.value })}
                  options={[{ value: '', label: 'No department' }, ...departments.map((d) => ({ value: d.id, label: d.name }))]}
                />
              </>
            )}
          </div>

          <fieldset className="space-y-3 rounded-xl border border-[#2A2A2A] p-4">
            <legend className="px-1 text-xs font-semibold uppercase tracking-wide text-zinc-300">Provisioning</legend>
            <label className="flex items-start gap-3 cursor-pointer">
              <input
                type="radio"
                name="passwordMode"
                checked={createForm.passwordMode === 'invite'}
                onChange={() => setCreateForm({ ...createForm, passwordMode: 'invite' })}
                className="mt-0.5 accent-[#D4AF37]"
              />
              <span className="text-sm text-zinc-300">
                Send invite email
                <span className="block text-xs text-[#A1A1AA]">
                  The user receives a secure link to set their own password. Recommended.
                </span>
              </span>
            </label>
            <label className="flex items-start gap-3 cursor-pointer">
              <input
                type="radio"
                name="passwordMode"
                checked={createForm.passwordMode === 'password'}
                onChange={() => setCreateForm({ ...createForm, passwordMode: 'password' })}
                className="mt-0.5 accent-[#D4AF37]"
              />
              <span className="text-sm text-zinc-300">
                Set an initial password
                <span className="block text-xs text-[#A1A1AA]">
                  Share it with the user through a secure channel. They should change it after first login.
                </span>
              </span>
            </label>
            {createForm.passwordMode === 'password' && (
              <Input
                label="Initial Password"
                type="password"
                value={createForm.password}
                onChange={(e) => setCreateForm({ ...createForm, password: e.target.value })}
                helperText="Min 6 characters with uppercase, lowercase, a number and a special character."
                autoComplete="new-password"
              />
            )}
          </fieldset>

          {createError && (
            <p role="alert" className="rounded-lg border border-[#EF4444]/30 bg-[#EF4444]/10 px-3 py-2 text-xs text-[#EF4444]">
              {createError}
            </p>
          )}

          <div className="flex justify-end gap-3 pt-1">
            <Button variant="secondary" size="sm" type="button" onClick={() => setCreateOpen(false)} disabled={createLoading}>
              Cancel
            </Button>
            <Button variant="primary" size="sm" type="submit" loading={createLoading}>
              Create Account
            </Button>
          </div>
        </form>
      </Modal>

      {/* Confirmation */}
      <ConfirmDialog
        isOpen={!!pendingAction}
        title={confirmCopy?.title || 'Confirm Action'}
        message={confirmCopy?.message || ''}
        confirmText={confirmCopy?.confirmText || 'Confirm'}
        variant={confirmCopy?.variant || 'danger'}
        onConfirm={() => confirmCopy?.onConfirm()}
        onCancel={() => !actionLoading && setPendingAction(null)}
        loading={actionLoading}
      />

      {/* Bulk failures detail */}
      <Modal isOpen={!!bulkFailures} onClose={() => setBulkFailures(null)} title="Bulk Action — Per-User Results" maxWidth="lg">
        <div className="space-y-4">
          <p className="text-sm text-zinc-300">
            {bulkFailures?.length} account{bulkFailures?.length === 1 ? '' : 's'} could not be updated. Everything else
            completed successfully.
          </p>
          <div className="max-h-72 overflow-y-auto rounded-xl border border-[#2A2A2A]">
            <table className="w-full text-left text-sm">
              <thead className="bg-[#141414] text-xs uppercase tracking-wider text-[#A1A1AA]">
                <tr>
                  <th className="px-4 py-2.5 font-semibold">User</th>
                  <th className="px-4 py-2.5 font-semibold">Reason</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[#2A2A2A]/80">
                {(bulkFailures || []).map((f) => (
                  <tr key={f.user_id}>
                    <td className="px-4 py-3 text-zinc-200">
                      {users.find((u) => u.id === f.user_id)?.name || f.user_id}
                    </td>
                    <td className="px-4 py-3 text-xs text-[#EF4444]">{f.reason}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="flex justify-end pt-1">
            <Button variant="secondary" size="sm" onClick={() => setBulkFailures(null)}>
              Close
            </Button>
          </div>
        </div>
      </Modal>
    </PageContainer>
  );
};

export default Users;

"use client";
import React, { useState, useEffect } from 'react';
import PortalLayout from '../../components/portal-shared/PortalLayout';
import { Card, MetricCard, StatusBadge, Button, LoadingSkeleton, EmptyState, Modal } from '../../components/portal-shared/SharedComponents';
import { supabaseRest } from '../../api/supabaseClient.js';

export default function ClientPortal() {
  const [activeTab, setActiveTab] = useState('projects');
  const [loading, setLoading] = useState(true);

  // Client records
  const [myProjects, setMyProjects] = useState([]);
  const [myInvoices, setMyInvoices] = useState([]);
  const [myTickets, setMyTickets] = useState([]);
  const [myContracts, setMyContracts] = useState([]);

  // Support Ticket Modal
  const [ticketModalOpen, setTicketModalOpen] = useState(false);
  const [ticketLoading, setTicketLoading] = useState(false);
  const [newTicket, setNewTicket] = useState({
    subject: '',
    description: '',
    priority: 'medium',
  });

  const loadData = async () => {
    setLoading(true);
    try {
      const [projRes, invRes, tickRes, contRes] = await Promise.all([
        supabaseRest('projects', { query: '?select=*&limit=20' }).catch(() => []),
        supabaseRest('invoices', { query: '?select=*&limit=20' }).catch(() => []),
        supabaseRest('tickets', { query: '?select=*&order=created_at.desc&limit=20' }).catch(() => []),
        supabaseRest('contracts', { query: '?select=*&limit=20' }).catch(() => []),
      ]);

      setMyProjects(projRes || []);
      setMyInvoices(invRes || []);
      setMyTickets(tickRes || []);
      setMyContracts(contRes || []);
    } catch (err) {
      console.error('Failed to load client records:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleCreateTicket = async (e) => {
    e.preventDefault();
    setTicketLoading(true);
    try {
      await supabaseRest('tickets', {
        method: 'POST',
        body: {
          subject: newTicket.subject,
          description: newTicket.description,
          priority: newTicket.priority,
          status: 'open',
        },
      });
      setTicketModalOpen(false);
      setNewTicket({ subject: '', description: '', priority: 'medium' });
      await loadData();
    } catch (err) {
      alert(`Failed to create ticket: ${err.message}`);
    } finally {
      setTicketLoading(false);
    }
  };

  const navSections = [
    {
      title: 'Client Workspace',
      items: [
        { label: 'Active Engagements', path: '/client', icon: '📁', badge: myProjects.length },
        { label: 'Billing & Invoices', path: '#invoices', icon: '💳', badge: myInvoices.length },
        { label: 'Support Tickets', path: '#tickets', icon: '🎫', badge: myTickets.filter(t => t.status === 'open').length },
        { label: 'Contracts & Agreements', path: '#contracts', icon: '📜', badge: myContracts.length },
      ],
    },
  ];

  return (
    <PortalLayout portalName="Client Portal" portalBadge="Customer Workspace" navSections={navSections}>
      {/* Navigation Bar Header (No extra top heading above navbar) */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between border-b border-[#2a2a2a] mb-6 pb-2 gap-3 overflow-x-auto">
        <div className="flex items-center gap-2 overflow-x-auto">
          {['projects', 'invoices', 'tickets', 'contracts'].map((tab) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`px-3.5 py-2 text-xs font-semibold capitalize whitespace-nowrap border-b-2 transition-colors ${
                activeTab === tab
                  ? 'border-[#d4af37] text-[#d4af37]'
                  : 'border-transparent text-zinc-400 hover:text-white'
              }`}
            >
              {tab}
            </button>
          ))}
        </div>
        <div className="flex items-center gap-2 shrink-0">
          <Button variant="outline" size="sm" onClick={loadData} icon={<span>🔄</span>}>
            Refresh
          </Button>
          <Button variant="gold" size="sm" onClick={() => setTicketModalOpen(true)} icon={<span>+</span>}>
            Open Support Ticket
          </Button>
        </div>
      </div>

      {/* Metric Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
        <MetricCard
          label="Active Projects"
          value={myProjects.length}
          trend="up"
          change="In progress"
          icon={<span>📁</span>}
        />
        <MetricCard
          label="Invoices"
          value={`$${myInvoices.reduce((a, b) => a + Number(b.amount || 0), 0).toLocaleString()}`}
          trend="neutral"
          change={`${myInvoices.length} invoices`}
          icon={<span>💳</span>}
        />
        <MetricCard
          label="Support Tickets"
          value={myTickets.length}
          trend={myTickets.filter(t => t.status === 'open').length > 0 ? 'down' : 'up'}
          change={`${myTickets.filter(t => t.status === 'open').length} open`}
          icon={<span>🎫</span>}
        />
        <MetricCard
          label="Contracts"
          value={myContracts.length}
          trend="up"
          change="Master agreements"
          icon={<span>📜</span>}
        />
      </div>

      {loading ? (
        <LoadingSkeleton count={4} height="h-28" />
      ) : (
        <>
          {/* TAB 1: PROJECTS */}
          {activeTab === 'projects' && (
            <Card title="Projects & Milestones" subtitle="Live progress and deliverables">
              {myProjects.length === 0 ? (
                <EmptyState title="No Active Projects" message="Your active engineering projects will appear here." />
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {myProjects.map((p) => (
                    <div key={p.id} className="p-4 rounded-xl bg-[#141414] border border-[#2a2a2a] hover:border-[#d4af37]/30 transition-colors">
                      <div className="flex items-center justify-between">
                        <h4 className="font-semibold text-white text-sm">{p.name}</h4>
                        <StatusBadge status={p.status || 'in progress'} />
                      </div>
                      <p className="text-xs text-zinc-400 mt-1">{p.description || 'Enterprise delivery project.'}</p>
                      <div className="mt-4 pt-3 border-t border-[#2a2a2a]">
                        <div className="flex justify-between text-xs text-zinc-400 mb-1">
                          <span>Delivery Progress</span>
                          <span className="font-bold text-[#d4af37]">{p.progress || 0}%</span>
                        </div>
                        <div className="w-full bg-[#222] rounded-full h-1.5 overflow-hidden">
                          <div className="bg-[#d4af37] h-full" style={{ width: `${p.progress || 0}%` }}></div>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </Card>
          )}

          {/* TAB 2: INVOICES */}
          {activeTab === 'invoices' && (
            <Card title="Commercial Invoices" subtitle="Billing statements and payment status">
              <div className="overflow-x-auto">
                <table className="w-full text-left text-xs">
                  <thead className="bg-[#121212] text-zinc-400 uppercase text-[10px] tracking-wider border-b border-[#2a2a2a]">
                    <tr>
                      <th className="py-3 px-4">Invoice #</th>
                      <th className="py-3 px-4">Amount</th>
                      <th className="py-3 px-4">Due Date</th>
                      <th className="py-3 px-4">Status</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[#2a2a2a]">
                    {myInvoices.map((inv) => (
                      <tr key={inv.id} className="hover:bg-white/[0.02]">
                        <td className="py-3 px-4 font-mono font-semibold text-white">{inv.invoice_number}</td>
                        <td className="py-3 px-4 font-mono font-bold text-[#d4af37]">${Number(inv.amount || 0).toLocaleString()}</td>
                        <td className="py-3 px-4 text-zinc-400">{inv.due_date || 'N/A'}</td>
                        <td className="py-3 px-4"><StatusBadge status={inv.status} /></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </Card>
          )}

          {/* TAB 3: TICKETS */}
          {activeTab === 'tickets' && (
            <Card
              title="Support & SLA Tickets"
              subtitle="Direct engineering escalation and customer inquiries"
              action={
                <Button size="sm" variant="gold" onClick={() => setTicketModalOpen(true)}>
                  + Open Ticket
                </Button>
              }
            >
              {myTickets.length === 0 ? (
                <EmptyState title="No Support Tickets" message="Need technical help? Submit a ticket anytime." />
              ) : (
                <div className="space-y-3">
                  {myTickets.map((t) => (
                    <div key={t.id} className="p-3.5 rounded-lg bg-[#141414] border border-[#2a2a2a] flex items-center justify-between">
                      <div>
                        <h4 className="text-xs font-semibold text-white">{t.subject}</h4>
                        <p className="text-[11px] text-zinc-400 mt-0.5">{t.description || 'Support request'}</p>
                      </div>
                      <div className="flex items-center gap-2">
                        <span className="text-[10px] uppercase font-mono px-2 py-0.5 rounded bg-[#222] text-zinc-400">{t.priority}</span>
                        <StatusBadge status={t.status || 'open'} />
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </Card>
          )}

          {/* TAB 4: CONTRACTS */}
          {activeTab === 'contracts' && (
            <Card title="Agreements & Commercial Terms" subtitle="Master service agreements and NDA records">
              <div className="overflow-x-auto">
                <table className="w-full text-left text-xs">
                  <thead className="bg-[#121212] text-zinc-400 uppercase text-[10px] tracking-wider border-b border-[#2a2a2a]">
                    <tr>
                      <th className="py-3 px-4">Agreement</th>
                      <th className="py-3 px-4">Value</th>
                      <th className="py-3 px-4">Status</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[#2a2a2a]">
                    {myContracts.map((c) => (
                      <tr key={c.id} className="hover:bg-white/[0.02]">
                        <td className="py-3 px-4 font-semibold text-white">{c.title || 'Master Service Agreement'}</td>
                        <td className="py-3 px-4 font-mono text-[#d4af37]">${Number(c.value || 0).toLocaleString()}</td>
                        <td className="py-3 px-4"><StatusBadge status={c.status || 'active'} /></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </Card>
          )}
        </>
      )}

      {/* CREATE TICKET MODAL */}
      <Modal isOpen={ticketModalOpen} onClose={() => setTicketModalOpen(false)} title="Open Support Ticket">
        <form onSubmit={handleCreateTicket} className="space-y-4">
          <div>
            <label className="block text-xs font-medium text-zinc-300 mb-1">Subject</label>
            <input
              required
              type="text"
              value={newTicket.subject}
              onChange={(e) => setNewTicket({ ...newTicket, subject: e.target.value })}
              className="w-full px-3 py-2 bg-[#121212] border border-[#2a2a2a] rounded-lg text-xs text-white focus:outline-none focus:border-[#d4af37]"
              placeholder="e.g. Inquire about milestone 3 deliverable"
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-zinc-300 mb-1">Priority</label>
            <select
              value={newTicket.priority}
              onChange={(e) => setNewTicket({ ...newTicket, priority: e.target.value })}
              className="w-full px-3 py-2 bg-[#121212] border border-[#2a2a2a] rounded-lg text-xs text-white focus:outline-none focus:border-[#d4af37]"
            >
              <option value="low">Low</option>
              <option value="medium">Medium</option>
              <option value="high">High</option>
              <option value="critical">Critical</option>
            </select>
          </div>
          <div>
            <label className="block text-xs font-medium text-zinc-300 mb-1">Description</label>
            <textarea
              required
              rows={3}
              value={newTicket.description}
              onChange={(e) => setNewTicket({ ...newTicket, description: e.target.value })}
              className="w-full px-3 py-2 bg-[#121212] border border-[#2a2a2a] rounded-lg text-xs text-white focus:outline-none focus:border-[#d4af37]"
              placeholder="Provide details on your request or issue..."
            />
          </div>
          <Button type="submit" variant="gold" loading={ticketLoading} className="w-full py-2">
            Submit Ticket
          </Button>
        </form>
      </Modal>
    </PortalLayout>
  );
}

"use client";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import React from 'react';
import { useLayout } from '../../../app/providers/LayoutProvider';
import { useAuth } from '../../../auth/auth.context';
import { Icon } from '../../../shared/components';

export interface ClientNavItem {
  label: string;
  path: string;
  icon: string;
  badge?: string;
}

export interface ClientNavGroup {
  title: string;
  items: ClientNavItem[];
}

export const clientNavGroups: ClientNavGroup[] = [
  {
    title: 'Overview',
    items: [
      { label: 'Client Overview', path: '/client', icon: 'home' },
    ],
  },
  {
    title: 'Project & SOW',
    items: [
      { label: 'Active Projects', path: '/client/projects', icon: 'folder' },
      { label: 'Project Milestones', path: '/client/milestones', icon: 'calendar' },
      { label: 'SOW Deliverables', path: '/client/deliverables', icon: 'check' },
      { label: 'Deliverable Files', path: '/client/files', icon: 'database' },
    ],
  },
  {
    title: 'Commercial & Financials',
    items: [
      { label: 'Contracts & MSAs', path: '/client/contracts', icon: 'clipboard' },
      { label: 'Billing & Invoices', path: '/client/invoices', icon: 'file' },
      { label: 'Payment Receipts', path: '/client/payments', icon: 'wallet' },
    ],
  },
  {
    title: 'Communication & Reports',
    items: [
      { label: 'Scheduled Meetings', path: '/client/meetings', icon: 'users' },
      { label: 'Support & SLA Tickets', path: '/client/support', icon: 'shield' },
      { label: 'Executive Reports', path: '/client/reports', icon: 'chart' },
      { label: 'Notifications', path: '/client/notifications', icon: 'bell' },
    ],
  },
];

export const ClientSidebar: React.FC = () => {
  const pathname = usePathname();
  const router = useRouter();
  const { user } = useAuth();
  const { sidebarOpen, setSidebarOpen } = useLayout();

  const isActive = (path: string) =>
    path === '/client'
      ? pathname === '/client'
      : pathname === path || pathname?.startsWith(`${path}/`);

  return (
    <>
      {sidebarOpen && (
        <div
          className="fixed inset-0 z-40 bg-black/70 backdrop-blur-sm lg:hidden transition-opacity"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      <aside
        className={`fixed lg:static top-0 bottom-0 left-0 z-50 w-64 bg-[#141414] border-r border-[#2A2A2A] flex flex-col flex-shrink-0 h-full transform transition-transform duration-200 ease-in-out ${
          sidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'
        }`}
      >
        {/* Brand Header */}
        <div className="h-16 px-4 border-b border-[#2A2A2A] flex items-center justify-between flex-shrink-0">
          <Link href="/client" className="flex items-center space-x-2.5 min-w-0">
            <img src="/logo/logo-icon.svg" alt="VPD" className="h-8 w-8" />
            <div className="min-w-0">
              <h1 className="text-[13px] font-bold text-white tracking-wide leading-none truncate">
                CLIENT PORTAL
              </h1>
              <p className="mt-1 text-[9px] text-[#D4AF37] uppercase font-semibold tracking-[0.18em]">
                Executive Workspace
              </p>
            </div>
          </Link>
          <button
            onClick={() => setSidebarOpen(false)}
            aria-label="Close navigation menu"
            className="lg:hidden text-[#A1A1AA] hover:text-white p-1.5 rounded-lg hover:bg-[#262626] transition-colors"
          >
            <Icon name="close" className="h-4 w-4" />
          </button>
        </div>

        {/* Executive Portal Switcher for Admin & Super Admin */}
        {['admin', 'super_admin'].includes(String(user?.role || '').toLowerCase()) && (
          <div className="px-3 pt-3 pb-2 border-b border-[#2A2A2A] bg-[#101010]">
            <label className="text-[10px] font-bold uppercase tracking-wider text-[#d4af37] flex items-center gap-1.5 mb-1.5">
              <span>⚡</span> Switch Portal
            </label>
            <select
              aria-label="Switch Portal"
              value="/client"
              onChange={(e) => router.push(e.target.value)}
              className="w-full bg-[#181818] border border-[#d4af37]/40 rounded-lg px-2.5 py-1.5 text-xs text-white focus:outline-none focus:border-[#d4af37] font-medium cursor-pointer"
            >
              <option value="/admin">👑 Admin & Executive</option>
              <option value="/hr">👥 HR & Workforce</option>
              <option value="/delivery">📁 Delivery & Projects</option>
              <option value="/sales">💼 Sales & CRM</option>
              <option value="/employee">👤 Employee Portal</option>
              <option value="/client">🏢 Client Portal</option>
            </select>
          </div>
        )}

        {/* Nav Items */}
        <nav className="flex-1 min-h-0 overflow-y-auto px-3 py-4 space-y-5 [scrollbar-width:thin] [scrollbar-color:#2a2a2a_transparent]">
          {clientNavGroups.map((group) => (
            <div key={group.title}>
              <p className="px-3 mb-2 text-[11px] font-bold uppercase tracking-wider text-[#D4AF37] flex items-center gap-1.5">
                <span className="w-1.5 h-1.5 rounded-full bg-[#D4AF37]/70" />
                {group.title}
              </p>
              <div className="space-y-0.5">
                {group.items.map((item) => {
                  const active = isActive(item.path);
                  return (
                    <Link
                      key={item.path}
                      href={item.path}
                      onClick={() => setSidebarOpen(false)}
                      aria-current={active ? 'page' : undefined}
                      className={`group relative flex items-center gap-2.5 px-3 py-2 rounded-lg text-[12.5px] font-medium transition-all duration-150 ${
                        active
                          ? 'bg-[#D4AF37]/10 text-[#F0D67C]'
                          : 'text-[#A1A1AA] hover:text-white hover:bg-[#1E1E1E]'
                      }`}
                    >
                      {active && (
                        <span className="absolute left-0 top-1/2 -translate-y-1/2 h-5 w-[3px] rounded-r-full bg-[#D4AF37]" />
                      )}
                      <Icon
                        name={item.icon}
                        className={`h-[18px] w-[18px] flex-shrink-0 ${
                          active ? 'text-[#D4AF37]' : 'text-[#71717A] group-hover:text-[#A1A1AA]'
                        }`}
                      />
                      <span className="truncate">{item.label}</span>
                    </Link>
                  );
                })}
              </div>
            </div>
          ))}
        </nav>

        {/* Bottom Status Card */}
        <div className="p-3 border-t border-[#2A2A2A] flex-shrink-0">
          <div className="rounded-xl border border-[#2A2A2A] bg-[#181818] px-3 py-2.5">
            <div className="flex items-center gap-2">
              <span className="relative flex h-2 w-2">
                <span className="absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-60 animate-ping" />
                <span className="relative flex h-2 w-2 rounded-full bg-emerald-500" />
              </span>
              <p className="text-[10px] font-semibold text-white">Encrypted Workspace</p>
            </div>
            <p className="mt-1 text-[10px] text-[#71717A] font-mono">SLA Tier 1 · Active</p>
          </div>
        </div>
      </aside>
    </>
  );
};

export default ClientSidebar;

"use client";
import React, { useState, useEffect } from 'react';
import PortalLayout from '../../components/portal-shared/PortalLayout';
import { Card, MetricCard, StatusBadge, Button, LoadingSkeleton, EmptyState, Modal } from '../../components/portal-shared/SharedComponents';
import { supabaseRest } from '../../api/supabaseClient.js';
import { useAuth } from '../../context/AuthContext.jsx';

export default function EmployeePortal() {
  const { user } = useAuth();
  const [activeTab, setActiveTab] = useState('tasks');
  const [loading, setLoading] = useState(true);

  // Live state
  const [myTasks, setMyTasks] = useState([]);
  const [myAttendance, setMyAttendance] = useState([]);
  const [myLeaves, setMyLeaves] = useState([]);
  const [myTimesheets, setMyTimesheets] = useState([]);
  const [announcements, setAnnouncements] = useState([]);

  // Check-in state
  const [checkedInToday, setCheckedInToday] = useState(false);
  const [checkInLoading, setCheckInLoading] = useState(false);

  // Leave Form
  const [leaveModalOpen, setLeaveModalOpen] = useState(false);
  const [leaveLoading, setLeaveLoading] = useState(false);
  const [newLeave, setNewLeave] = useState({
    leave_type: 'casual',
    start_date: new Date().toISOString().split('T')[0],
    end_date: new Date(Date.now() + 86400000).toISOString().split('T')[0],
    reason: '',
  });

  // Timesheet Form
  const [timesheetModalOpen, setTimesheetModalOpen] = useState(false);
  const [timesheetLoading, setTimesheetLoading] = useState(false);
  const [newTimesheet, setNewTimesheet] = useState({
    hours: 8,
    date: new Date().toISOString().split('T')[0],
    description: '',
  });

  const loadData = async () => {
    setLoading(true);
    try {
      const today = new Date().toISOString().split('T')[0];
      const [taskRes, attRes, leaveRes, timeRes, annRes] = await Promise.all([
        supabaseRest('tasks', { query: '?select=*,project:projects(name)&limit=20' }).catch(() => []),
        supabaseRest('attendance', { query: '?order=date.desc&limit=15' }).catch(() => []),
        supabaseRest('leaves', { query: '?order=created_at.desc&limit=15' }).catch(() => []),
        supabaseRest('timesheets', { query: '?order=created_at.desc&limit=15' }).catch(() => []),
        supabaseRest('announcements', { query: '?order=created_at.desc&limit=10' }).catch(() => []),
      ]);

      setMyTasks(taskRes || []);
      setMyAttendance(attRes || []);
      setMyLeaves(leaveRes || []);
      setMyTimesheets(timeRes || []);
      setAnnouncements(annRes || []);

      const todayLog = (attRes || []).find(a => a.date === today && a.check_in);
      setCheckedInToday(Boolean(todayLog));
    } catch (err) {
      console.error('Failed to load employee records:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleToggleCheckIn = async () => {
    setCheckInLoading(true);
    try {
      const today = new Date().toISOString().split('T')[0];
      const now = new Date().toISOString();

      if (!checkedInToday) {
        // Check in
        await supabaseRest('attendance', {
          method: 'POST',
          body: {
            date: today,
            check_in: now,
            status: 'present',
          },
        });
        setCheckedInToday(true);
      } else {
        // Check out
        await supabaseRest('attendance', {
          method: 'PATCH',
          query: `?date=eq.${today}`,
          body: {
            check_out: now,
          },
        });
        alert('Successfully checked out for today!');
      }
      await loadData();
    } catch (err) {
      alert(`Attendance action failed: ${err.message}`);
    } finally {
      setCheckInLoading(false);
    }
  };

  const handleApplyLeave = async (e) => {
    e.preventDefault();
    setLeaveLoading(true);
    try {
      await supabaseRest('leaves', {
        method: 'POST',
        body: {
          ...newLeave,
          status: 'pending',
        },
      });
      setLeaveModalOpen(false);
      setNewLeave({
        leave_type: 'casual',
        start_date: new Date().toISOString().split('T')[0],
        end_date: new Date(Date.now() + 86400000).toISOString().split('T')[0],
        reason: '',
      });
      await loadData();
    } catch (err) {
      alert(`Leave application failed: ${err.message}`);
    } finally {
      setLeaveLoading(false);
    }
  };

  const handleSubmitTimesheet = async (e) => {
    e.preventDefault();
    setTimesheetLoading(true);
    try {
      await supabaseRest('timesheets', {
        method: 'POST',
        body: {
          hours_spent: newTimesheet.hours,
          date: newTimesheet.date,
          description: newTimesheet.description,
          status: 'submitted',
        },
      });
      setTimesheetModalOpen(false);
      setNewTimesheet({
        hours: 8,
        date: new Date().toISOString().split('T')[0],
        description: '',
      });
      await loadData();
    } catch (err) {
      alert(`Timesheet submission failed: ${err.message}`);
    } finally {
      setTimesheetLoading(false);
    }
  };

  const handleTaskStatus = async (taskId, newStatus) => {
    try {
      await supabaseRest('tasks', {
        method: 'PATCH',
        query: `?id=eq.${taskId}`,
        body: { status: newStatus },
      });
      await loadData();
    } catch (err) {
      alert(`Error updating task status: ${err.message}`);
    }
  };

  const navSections = [
    {
      title: 'My Daily Work',
      items: [
        { label: 'Assigned Tasks', path: '/employee', icon: '📝', badge: myTasks.length },
        { label: 'Attendance & Log', path: '#attendance', icon: '⏱️', badge: checkedInToday ? 'Checked in' : 'Pending' },
        { label: 'Leave Requests', path: '#leaves', icon: '🏖️', badge: myLeaves.length },
        { label: 'My Timesheets', path: '#timesheets', icon: '⏳', badge: myTimesheets.length },
        { label: 'Company Announcements', path: '#announcements', icon: '📢', badge: announcements.length },
      ],
    },
  ];

  return (
    <PortalLayout portalName="Employee Portal" portalBadge="Personnel Workspace" navSections={navSections}>
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-white">Employee Self-Service</h1>
          <p className="text-xs text-zinc-400 mt-1">Welcome back, {user?.name || 'Staff'}. Manage your daily duties, attendance, and leave requests.</p>
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant={checkedInToday ? 'secondary' : 'gold'}
            size="sm"
            onClick={handleToggleCheckIn}
            loading={checkInLoading}
            icon={<span>⏱️</span>}
          >
            {checkedInToday ? 'Check Out Today' : 'Check In Today'}
          </Button>
          <Button variant="outline" size="sm" onClick={() => setLeaveModalOpen(true)} icon={<span>+</span>}>
            Apply Leave
          </Button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-[#2a2a2a] mb-6 overflow-x-auto gap-2">
        {['tasks', 'attendance', 'leaves', 'timesheets', 'announcements'].map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-4 py-2.5 text-xs font-semibold capitalize whitespace-nowrap border-b-2 transition-colors ${
              activeTab === tab
                ? 'border-[#d4af37] text-[#d4af37]'
                : 'border-transparent text-zinc-400 hover:text-white'
            }`}
          >
            {tab}
          </button>
        ))}
      </div>

      {/* Metric Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
        <MetricCard
          label="Today's Status"
          value={checkedInToday ? 'Present' : 'Not Checked In'}
          trend={checkedInToday ? 'up' : 'down'}
          change={checkedInToday ? 'Shift active' : 'Action needed'}
          icon={<span>⏱️</span>}
        />
        <MetricCard
          label="My Open Tasks"
          value={myTasks.filter(t => t.status !== 'completed').length}
          trend="neutral"
          change="Pending delivery"
          icon={<span>📝</span>}
        />
        <MetricCard
          label="Leave Balance"
          value="18 Days"
          trend="up"
          change="Casual + Earned"
          icon={<span>🏖️</span>}
        />
        <MetricCard
          label="Logged Timesheets"
          value={`${myTimesheets.length} Logs`}
          trend="up"
          change="Submitted"
          icon={<span>⏳</span>}
        />
      </div>

      {loading ? (
        <LoadingSkeleton count={4} height="h-28" />
      ) : (
        <>
          {/* TAB 1: MY TASKS */}
          {activeTab === 'tasks' && (
            <Card title="My Assigned Tasks" subtitle="Active sprint backlog tasks">
              {myTasks.length === 0 ? (
                <EmptyState title="No Tasks Assigned" message="You do not have any open tasks assigned right now." />
              ) : (
                <div className="space-y-3">
                  {myTasks.map((t) => (
                    <div key={t.id} className="p-4 rounded-xl bg-[#141414] border border-[#2a2a2a] flex flex-col sm:flex-row sm:items-center justify-between gap-3 hover:border-[#d4af37]/30 transition-colors">
                      <div>
                        <div className="flex items-center gap-2">
                          <h4 className="text-xs font-semibold text-white">{t.title}</h4>
                          <span className="text-[10px] text-[#d4af37] bg-[#d4af37]/10 px-2 py-0.5 rounded font-mono">
                            {t.project?.name || 'Project'}
                          </span>
                        </div>
                        <p className="text-xs text-zinc-400 mt-1">{t.description || 'Deliverable task.'}</p>
                      </div>
                      <div className="flex items-center gap-2 shrink-0">
                        <StatusBadge status={t.status || 'todo'} />
                        {t.status !== 'completed' && (
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => handleTaskStatus(t.id, t.status === 'todo' ? 'in_progress' : 'completed')}
                          >
                            {t.status === 'todo' ? 'Start' : 'Mark Done'}
                          </Button>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </Card>
          )}

          {/* TAB 2: ATTENDANCE */}
          {activeTab === 'attendance' && (
            <Card
              title="Attendance History"
              subtitle="Personal log of daily work sessions"
              action={
                <Button size="sm" variant="gold" onClick={handleToggleCheckIn} loading={checkInLoading}>
                  {checkedInToday ? 'Check Out' : 'Check In'}
                </Button>
              }
            >
              <div className="overflow-x-auto">
                <table className="w-full text-left text-xs">
                  <thead className="bg-[#121212] text-zinc-400 uppercase text-[10px] tracking-wider border-b border-[#2a2a2a]">
                    <tr>
                      <th className="py-3 px-4">Date</th>
                      <th className="py-3 px-4">Check-in</th>
                      <th className="py-3 px-4">Check-out</th>
                      <th className="py-3 px-4">Status</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[#2a2a2a]">
                    {myAttendance.map((a) => (
                      <tr key={a.id} className="hover:bg-white/[0.02]">
                        <td className="py-3 px-4 font-mono text-white">{a.date}</td>
                        <td className="py-3 px-4 text-zinc-300">{a.check_in ? new Date(a.check_in).toLocaleTimeString() : '—'}</td>
                        <td className="py-3 px-4 text-zinc-300">{a.check_out ? new Date(a.check_out).toLocaleTimeString() : '—'}</td>
                        <td className="py-3 px-4"><StatusBadge status={a.status || 'present'} /></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </Card>
          )}

          {/* TAB 3: LEAVES */}
          {activeTab === 'leaves' && (
            <Card
              title="My Leave Applications"
              subtitle="Submit and track time-off requests"
              action={
                <Button size="sm" variant="gold" onClick={() => setLeaveModalOpen(true)}>
                  + Apply Leave
                </Button>
              }
            >
              {myLeaves.length === 0 ? (
                <EmptyState title="No Leave Applications" message="You have not submitted any leave requests yet." />
              ) : (
                <div className="overflow-x-auto">
                  <table className="w-full text-left text-xs">
                    <thead className="bg-[#121212] text-zinc-400 uppercase text-[10px] tracking-wider border-b border-[#2a2a2a]">
                      <tr>
                        <th className="py-3 px-4">Type</th>
                        <th className="py-3 px-4">Period</th>
                        <th className="py-3 px-4">Reason</th>
                        <th className="py-3 px-4">Approval Status</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-[#2a2a2a]">
                      {myLeaves.map((l) => (
                        <tr key={l.id} className="hover:bg-white/[0.02]">
                          <td className="py-3 px-4 font-semibold capitalize text-white">{l.leave_type}</td>
                          <td className="py-3 px-4 text-zinc-300">{l.start_date} to {l.end_date}</td>
                          <td className="py-3 px-4 text-zinc-400 max-w-xs truncate">{l.reason || 'Personal leave'}</td>
                          <td className="py-3 px-4"><StatusBadge status={l.status} /></td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </Card>
          )}

          {/* TAB 4: TIMESHEETS */}
          {activeTab === 'timesheets' && (
            <Card
              title="My Timesheets"
              subtitle="Daily effort logs and activity reports"
              action={
                <Button size="sm" variant="gold" onClick={() => setTimesheetModalOpen(true)}>
                  + Submit Timesheet
                </Button>
              }
            >
              <div className="overflow-x-auto">
                <table className="w-full text-left text-xs">
                  <thead className="bg-[#121212] text-zinc-400 uppercase text-[10px] tracking-wider border-b border-[#2a2a2a]">
                    <tr>
                      <th className="py-3 px-4">Date</th>
                      <th className="py-3 px-4">Hours</th>
                      <th className="py-3 px-4">Activity Description</th>
                      <th className="py-3 px-4">Status</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[#2a2a2a]">
                    {myTimesheets.map((ts) => (
                      <tr key={ts.id} className="hover:bg-white/[0.02]">
                        <td className="py-3 px-4 font-mono text-white">{ts.date || new Date(ts.created_at).toLocaleDateString()}</td>
                        <td className="py-3 px-4 font-bold text-[#d4af37]">{ts.hours_spent || 8} hrs</td>
                        <td className="py-3 px-4 text-zinc-300 max-w-sm truncate">{ts.description || 'Sprint development tasks'}</td>
                        <td className="py-3 px-4"><StatusBadge status={ts.status || 'submitted'} /></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </Card>
          )}

          {/* TAB 5: ANNOUNCEMENTS */}
          {activeTab === 'announcements' && (
            <Card title="Corporate Announcements" subtitle="Internal notices from management">
              <div className="space-y-4">
                {announcements.map((a) => (
                  <div key={a.id} className="p-4 rounded-xl bg-[#141414] border border-[#2a2a2a]">
                    <div className="flex items-center justify-between">
                      <h4 className="font-semibold text-white text-sm">{a.title}</h4>
                      <span className="text-[10px] text-zinc-500">{new Date(a.created_at).toLocaleDateString()}</span>
                    </div>
                    <p className="text-xs text-zinc-300 mt-2">{a.content || a.message}</p>
                  </div>
                ))}
              </div>
            </Card>
          )}
        </>
      )}

      {/* APPLY LEAVE MODAL */}
      <Modal isOpen={leaveModalOpen} onClose={() => setLeaveModalOpen(false)} title="Apply for Leave">
        <form onSubmit={handleApplyLeave} className="space-y-4">
          <div>
            <label className="block text-xs font-medium text-zinc-300 mb-1">Leave Type</label>
            <select
              value={newLeave.leave_type}
              onChange={(e) => setNewLeave({ ...newLeave, leave_type: e.target.value })}
              className="w-full px-3 py-2 bg-[#121212] border border-[#2a2a2a] rounded-lg text-xs text-white focus:outline-none focus:border-[#d4af37]"
            >
              <option value="casual">Casual Leave</option>
              <option value="sick">Sick Leave</option>
              <option value="earned">Earned Leave</option>
              <option value="unpaid">Unpaid Leave</option>
            </select>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-medium text-zinc-300 mb-1">Start Date</label>
              <input
                required
                type="date"
                value={newLeave.start_date}
                onChange={(e) => setNewLeave({ ...newLeave, start_date: e.target.value })}
                className="w-full px-3 py-2 bg-[#121212] border border-[#2a2a2a] rounded-lg text-xs text-white focus:outline-none focus:border-[#d4af37]"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-zinc-300 mb-1">End Date</label>
              <input
                required
                type="date"
                value={newLeave.end_date}
                onChange={(e) => setNewLeave({ ...newLeave, end_date: e.target.value })}
                className="w-full px-3 py-2 bg-[#121212] border border-[#2a2a2a] rounded-lg text-xs text-white focus:outline-none focus:border-[#d4af37]"
              />
            </div>
          </div>
          <div>
            <label className="block text-xs font-medium text-zinc-300 mb-1">Reason</label>
            <textarea
              required
              rows={3}
              value={newLeave.reason}
              onChange={(e) => setNewLeave({ ...newLeave, reason: e.target.value })}
              className="w-full px-3 py-2 bg-[#121212] border border-[#2a2a2a] rounded-lg text-xs text-white focus:outline-none focus:border-[#d4af37]"
              placeholder="Provide context for manager review..."
            />
          </div>
          <Button type="submit" variant="gold" loading={leaveLoading} className="w-full py-2">
            Submit Leave Request
          </Button>
        </form>
      </Modal>

      {/* SUBMIT TIMESHEET MODAL */}
      <Modal isOpen={timesheetModalOpen} onClose={() => setTimesheetModalOpen(false)} title="Submit Daily Timesheet">
        <form onSubmit={handleSubmitTimesheet} className="space-y-4">
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-medium text-zinc-300 mb-1">Date</label>
              <input
                required
                type="date"
                value={newTimesheet.date}
                onChange={(e) => setNewTimesheet({ ...newTimesheet, date: e.target.value })}
                className="w-full px-3 py-2 bg-[#121212] border border-[#2a2a2a] rounded-lg text-xs text-white focus:outline-none focus:border-[#d4af37]"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-zinc-300 mb-1">Hours Logged</label>
              <input
                required
                type="number"
                min="1"
                max="16"
                value={newTimesheet.hours}
                onChange={(e) => setNewTimesheet({ ...newTimesheet, hours: Number(e.target.value) })}
                className="w-full px-3 py-2 bg-[#121212] border border-[#2a2a2a] rounded-lg text-xs text-white focus:outline-none focus:border-[#d4af37]"
              />
            </div>
          </div>
          <div>
            <label className="block text-xs font-medium text-zinc-300 mb-1">Work Completed</label>
            <textarea
              required
              rows={3}
              value={newTimesheet.description}
              onChange={(e) => setNewTimesheet({ ...newTimesheet, description: e.target.value })}
              className="w-full px-3 py-2 bg-[#121212] border border-[#2a2a2a] rounded-lg text-xs text-white focus:outline-none focus:border-[#d4af37]"
              placeholder="Tasks accomplished, bug fixes, feature implementations..."
            />
          </div>
          <Button type="submit" variant="gold" loading={timesheetLoading} className="w-full py-2">
            Log Timesheet
          </Button>
        </form>
      </Modal>
    </PortalLayout>
  );
}

"use client";
import Link from "next/link";
import { usePathname } from "next/navigation";
import React from 'react';
import { useLayout } from '../../../app/providers/LayoutProvider';
import { Icon } from '../../../shared/components';

export interface EmployeeNavItem {
  label: string;
  path: string;
  icon: string;
}

export interface EmployeeNavGroup {
