            >
              <option value="/admin">👑 Admin & Executive</option>
              <option value="/hr">👥 HR & Workforce</option>
              <option value="/delivery">📁 Delivery & Projects</option>
              <option value="/sales">💼 Sales & CRM</option>
              <option value="/employee">👤 Employee Portal</option>
              <option value="/client">🏢 Client Portal</option>
            </select>
          </div>
        )}

        {/* Nav Items */}
        <nav className="flex-1 min-h-0 overflow-y-auto px-3 py-4 space-y-5 [scrollbar-width:thin] [scrollbar-color:#2a2a2a_transparent]">
          {salesNavGroups.map((group) => (
            <div key={group.title}>
              <p className="px-3 mb-2 text-[11px] font-bold uppercase tracking-wider text-[#D4AF37] flex items-center gap-1.5">
                <span className="w-1.5 h-1.5 rounded-full bg-[#D4AF37]/70" />
                {group.title}
              </p>
              <div className="space-y-0.5">
                {group.items.map((item) => {
                  const active = isActive(item.path);
                  return (
                    <Link
                      key={item.path}
                      href={item.path}
                      onClick={() => setSidebarOpen(false)}
                      aria-current={active ? 'page' : undefined}
                      className={`group relative flex items-center gap-2.5 px-3 py-2 rounded-lg text-[12.5px] font-medium transition-all duration-150 ${
                        active
                          ? 'bg-[#D4AF37]/10 text-[#F0D67C]'
                          : 'text-[#A1A1AA] hover:text-white hover:bg-[#1E1E1E]'
                      }`}
                    >
                      {active && (
                        <span className="absolute left-0 top-1/2 -translate-y-1/2 h-5 w-[3px] rounded-r-full bg-[#D4AF37]" />
                      )}
                      <Icon
                        name={item.icon}
                        className={`h-[18px] w-[18px] flex-shrink-0 ${
                          active ? 'text-[#D4AF37]' : 'text-[#71717A] group-hover:text-[#A1A1AA]'
                        }`}
                      />
                      <span className="truncate">{item.label}</span>
                    </Link>
                  );
                })}
              </div>
            </div>
          ))}
        </nav>

        {/* Bottom Status Card */}
        <div className="p-3 border-t border-[#2A2A2A] flex-shrink-0">
          <div className="rounded-xl border border-[#2A2A2A] bg-[#181818] px-3 py-2.5">
            <div className="flex items-center gap-2">
              <span className="relative flex h-2 w-2">
                <span className="absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-60 animate-ping" />
                <span className="relative flex h-2 w-2 rounded-full bg-emerald-500" />
              </span>
              <p className="text-[10px] font-semibold text-white">CRM Pipeline Live</p>
            </div>
            <p className="mt-1 text-[10px] text-[#71717A] font-mono">Q4 Targets · On Track</p>
          </div>
        </div>
      </aside>
    </>
  );
};

export default SalesSidebar;

"use client";
import { useRouter } from "next/navigation";
import React, { useEffect, useState } from 'react';

import { useAuth } from '../auth/auth.context';

export default function LoadingPage() {
  const { user, isAuthenticated, isLoading } = useAuth();
  const navigate = useRouter();
  const [progress, setProgress] = useState(15);
  const [statusMessage, setStatusMessage] = useState('Initializing VPD Security Environment...');

  useEffect(() => {
    const timer1 = setTimeout(() => {
      setProgress(45);
      setStatusMessage('Connecting to Enterprise Database...');
    }, 400);

    const timer2 = setTimeout(() => {
      setProgress(80);
      setStatusMessage('Resolving Role-Based Access Controls...');
    }, 900);

    const timer3 = setTimeout(() => {
      setProgress(100);
      setStatusMessage('Ready. Directing to your workspace...');
    }, 1400);

    const redirectTimer = setTimeout(() => {
      if (isLoading) return;

      if (!isAuthenticated || !user) {
        navigate.replace('/auth/login');
        return;
      }

      const role = String(user.role || '').toLowerCase();
      if (['super_admin', 'admin', 'finance'].includes(role)) navigate.replace('/admin');
      else if (['sales', 'marketing'].includes(role)) navigate.replace('/sales');
      else if (role === 'hr') navigate.replace('/hr');
      else if (role === 'project_manager') navigate.replace('/delivery');
      else if (role === 'client') navigate.replace('/client');
      else navigate.replace('/employee');
    }, 1700);

    return () => {
      clearTimeout(timer1);
      clearTimeout(timer2);
      clearTimeout(timer3);
      clearTimeout(redirectTimer);
    };
  }, [user, isAuthenticated, isLoading, navigate]);

  return (
    <div className="min-h-screen bg-[#0a0a0a] text-zinc-100 flex flex-col items-center justify-center p-6 antialiased select-none">
      {/* Background Subtle Ambience */}
      <div className="fixed inset-0 overflow-hidden pointer-events-none">
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[500px] h-[500px] bg-[#d4af37]/5 rounded-full blur-[120px]"></div>
      </div>

      <div className="relative z-10 w-full max-w-sm flex flex-col items-center text-center">
        {/* Animated Brand Logo Container */}
        <div className="relative mb-6">
          <div className="absolute inset-0 rounded-2xl bg-gradient-to-tr from-[#d4af37]/20 to-transparent blur-md animate-pulse"></div>
          <div className="relative w-20 h-20 rounded-2xl bg-[#121212] border border-[#2a2a2a] p-3.5 flex items-center justify-center shadow-2xl">
            <img src="/logo.webp" alt="VPD Logo" className="w-full h-full object-contain drop-shadow" />
          </div>
        </div>

        {/* Title */}
        <h1 className="text-xl font-bold tracking-tight text-white mb-1">
          VPD Technologies
        </h1>
        <p className="text-[11px] font-semibold text-[#d4af37] tracking-wider uppercase mb-8">
          Enterprise Operations Platform
        </p>

        {/* Progress Bar Container */}
        <div className="w-full bg-[#171717] border border-[#2a2a2a] rounded-full h-2 p-0.5 mb-3 overflow-hidden">
          <div
            className="bg-gradient-to-r from-[#d4af37] to-[#dfc067] h-full rounded-full transition-all duration-500 ease-out shadow-sm shadow-[#d4af37]/50"
            style={{ width: `${progress}%` }}
          ></div>
        </div>

        {/* Dynamic Status Text */}
        <div className="flex items-center gap-2 text-xs text-zinc-400 font-medium">
          <svg className="animate-spin h-3.5 w-3.5 text-[#d4af37]" viewBox="0 0 24 24" fill="none">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
          </svg>
          <span>{statusMessage}</span>
        </div>

        {/* Enterprise Security Badge */}
        <div className="mt-12 inline-flex items-center gap-2 px-3 py-1 rounded-full bg-[#121212] border border-[#2a2a2a] text-[10px] text-zinc-500">
          <span className="w-1.5 h-1.5 rounded-full bg-emerald-500"></span>
          <span>AES-256 Encrypted Session</span>
        </div>
      </div>
    </div>
  );
}

"use client";
import { useRouter } from "next/navigation";
import React, { useState } from 'react';

import { useAuth } from '../context/AuthContext.jsx';
import { Button } from '../components/portal-shared/SharedComponents';

export default function LoginPage() {
  const { login } = useAuth();
  const navigate = useRouter();

  const [email, setEmail] = useState('admin@vpdtechnologies.com');
  const [password, setPassword] = useState('Password123!');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [showDemoLogins, setShowDemoLogins] = useState(true);

  const demoAccounts = [
    { role: 'Admin', email: 'admin@vpdtechnologies.com', path: '/admin' },
    { role: 'Manager', email: 'pm@vpdtechnologies.com', path: '/delivery' },
    { role: 'HR', email: 'hr@vpdtechnologies.com', path: '/hr' },
    { role: 'Sales', email: 'sales@vpdtechnologies.com', path: '/sales' },
    { role: 'Client', email: 'client@vpdtechnologies.com', path: '/client' },
    { role: 'Employee', email: 'employee@vpdtechnologies.com', path: '/employee' },
  ];

  const handleSignIn = async (e) => {
    if (e) e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const authenticatedUser = await login(email, password);
      const role = String(authenticatedUser?.role || '').toLowerCase();

      // Redirect to authoritative portal
      switch (role) {
        case 'super_admin':
        case 'admin':
        case 'finance':
          navigate.push('/admin');
          break;
        case 'sales':
        case 'marketing':
          navigate.push('/sales');
          break;
        case 'hr':
          navigate.push('/hr');
          break;
        case 'project_manager':
          navigate.push('/delivery');
          break;
        case 'client':
          navigate.push('/client');
          break;
        default:
          navigate.push('/employee');
          break;
      }
    } catch (err) {
      setError(err.message || 'Login failed. Please check your credentials.');
    } finally {
      setLoading(false);
    }
  };

  const selectDemoAccount = (acc) => {
    setEmail(acc.email);
    setPassword('Password123!');
  };

  return (
    <div className="min-h-screen bg-[#0a0a0a] text-zinc-100 flex flex-col items-center justify-center p-4 antialiased">
      <div className="w-full max-w-md">
        {/* Brand Header */}
        <div className="text-center mb-6">
          <img src="/logo.webp" alt="VPD Technologies" className="h-14 mx-auto mb-3 object-contain" />
          <h1 className="text-2xl font-bold tracking-tight text-white">VPD Technologies</h1>
          <p className="text-xs text-[#d4af37] font-semibold uppercase tracking-wider mt-1">Enterprise Business Operations Platform</p>
        </div>

        {/* Login Card */}
        <div className="bg-[#121212] border border-[#2a2a2a] rounded-2xl p-7 shadow-2xl">
          <h2 className="text-lg font-semibold text-white mb-1">Sign In to Your Workspace</h2>
          <p className="text-xs text-zinc-400 mb-5">Enter your verified credentials to access your role-based portal.</p>

          {error && (
            <div className="mb-5 p-3 rounded-lg bg-rose-500/10 border border-rose-500/30 text-rose-300 text-xs flex items-center gap-2">
              <svg className="w-4 h-4 shrink-0 text-rose-400" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd"/>
              </svg>
              <span>{error}</span>
            </div>
          )}

          <form onSubmit={handleSignIn} className="space-y-4">
            <div>
              <label className="block text-xs font-semibold text-zinc-300 uppercase tracking-wider mb-1.5">Email Address</label>
              <input
                type="email"
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="name@vpdtechnologies.com"
                className="w-full px-3.5 py-2.5 bg-[#171717] border border-[#2a2a2a] rounded-lg text-sm text-white placeholder-zinc-500 focus:outline-none focus:border-[#d4af37] focus:ring-1 focus:ring-[#d4af37]"
              />
            </div>

            <div>
              <div className="flex items-center justify-between mb-1.5">
                <label className="block text-xs font-semibold text-zinc-300 uppercase tracking-wider">Password</label>
              </div>
              <input
                type="password"
                required
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="••••••••"
                className="w-full px-3.5 py-2.5 bg-[#171717] border border-[#2a2a2a] rounded-lg text-sm text-white placeholder-zinc-500 focus:outline-none focus:border-[#d4af37] focus:ring-1 focus:ring-[#d4af37]"
              />
            </div>

            <Button
              type="submit"
              variant="gold"
              loading={loading}
              className="w-full py-2.5 mt-2"
            >
              Sign In to Portal
            </Button>
          </form>

          {/* Quick Demo Role Selector */}
          <div className="mt-6 pt-5 border-t border-[#2a2a2a]">
            <button
              onClick={() => setShowDemoLogins(!showDemoLogins)}
              className="w-full flex items-center justify-between text-xs text-zinc-400 hover:text-white"
            >
              <span className="font-medium text-[11px] uppercase tracking-wider text-[#d4af37]">Verified Demo Portals</span>
              <span>{showDemoLogins ? '▲' : '▼'}</span>
            </button>

            {showDemoLogins && (
              <div className="mt-3 space-y-1.5">
                {demoAccounts.map((acc) => (
                  <button
                    key={acc.role}
                    type="button"
                    onClick={() => selectDemoAccount(acc)}
                    className="w-full flex items-center justify-between px-2.5 py-1.5 rounded-lg bg-[#181818] hover:bg-[#202020] border border-[#2a2a2a] text-left transition-colors"
                  >
                    <span className="text-xs font-medium text-white">{acc.role}</span>
                    <span className="text-[10px] text-zinc-400 font-mono truncate max-w-[150px]">{acc.email}</span>
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>

        <p className="text-center text-[11px] text-zinc-500 mt-6">
          © {new Date().getFullYear()} VPD Technologies. All rights reserved.
        </p>
      </div>
    </div>
  );
}

import Link from "next/link";

import Icon from '../components/ui/Icon';
import useDocumentTitle from '../hooks/useDocumentTitle.js';

const QUICK_LINKS = [
  { to: '/services', label: 'Services' },
  { to: '/solutions', label: 'Solutions' },
  { to: '/about', label: 'About Us' },
  { to: '/contact', label: 'Contact' },
  { to: '/blog', label: 'Blog' },
  { to: '/faq', label: 'FAQ' },
];

export default function NotFound() {
  useDocumentTitle('Page Not Found | VPD Technologies');
  return (
    <div className="min-h-screen flex items-center justify-center bg-surface-container px-margin-mobile md:px-margin-desktop">
      <div className="text-center max-w-lg">
        <p className="font-stat text-stat-lg text-brand mb-4">404</p>
        <h1 className="font-display text-display-md text-brand-dark mb-4">Page Not Found</h1>
        <p className="text-body-md text-ink-muted mb-8">
          The page you&apos;re looking for doesn&apos;t exist or has been moved. Please check the URL or use
          the links below to find what you need.
        </p>
        <div className="flex flex-wrap justify-center gap-3 mb-10">
          {QUICK_LINKS.map((link) => (
            <Link
              key={link.to}
              href={link.to}
              className="text-body-sm text-brand hover:text-brand-dark underline underline-offset-2"
            >
              {link.label}
            </Link>
          ))}
        </div>
        <Link
          href="/"
          className="inline-flex items-center gap-2 bg-brand text-white px-6 py-3 rounded-lg font-label-caps text-label-caps uppercase hover:bg-brand-dark transition-colors"
        >
          <Icon name="arrow_back" /> Back to Home
        </Link>
      </div>
    </div>
  );
}

